programs.haiku:
"""Fires on the number word "two" and on technical nouns describing how a system behaves
or is arranged (behavior, structure, solution, pattern, distribution, equation, ...), and on
"of" right after such a noun ("the behavior of", "the distribution of"). It is slightly
negative on "of" after purpose nouns ("the objective of", "the goal of"). Everything else
predicts 0. Values are rough activation sizes read off training rows, not fitted."""
READS = ()

TWO = {" two", " Two", "Two", "两个", "兩", " deux", " twice"}
BEHAVIOR = {" behavior", " behaviour", " behaviors", " behaviours", " Behavior", " Behaviour",
            " behavior", " 现象", "现象"}
STRUCTURE = {" structure", " structures", " solution", " solutions", " pattern", " patterns",
             " distribution", " distributions", " equation", " equations", " relationship",
             " relationships", " dynamics", " motion", " phase", " phases", " oscillation",
             " oscill", " transition", " wave", " roots", " root", " properties", " symmetry",
             " dependence", " correlation", " correlations", " fluctuations", " eigen", " motion"}
PURPOSE = {" objective", " goal", " practice", " treatment", " help", " assistance", " accuracy",
           " implementation", " purpose", " aim"}
SYSTEM_OF = BEHAVIOR | STRUCTURE | {" shape", " position", " positions", " movement", " spread",
                                    " growth", " increase", " existence", " features"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in TWO:
        return None, 0.8
    if tok in BEHAVIOR:
        return None, 1.0
    if tok in STRUCTURE:
        return None, 0.6
    if tok == " of":
        if prev in SYSTEM_OF:
            return None, 1.0
        if prev in PURPOSE:
            return None, -0.3
    return None, 0.0

programs.luna:
"""Estimate a sparse response to pair words and mathematical structure terms."""
READS = ()

PAIR_WORDS = {
    "two", "twice", "pair", "pairs", "both", "couple", "double",
    "dual", "兩", "两", "两个", "兩個",
}
MATH_TERMS = {
    "root", "roots", "solution", "solutions", "equation", "equations",
    "distribution", "structure", "relationship", "relation", "points",
    "wave", "eigen", "pattern", "system", "interactions", "behaviour",
    "behavior", "critical", "forms", "periodic", "movements",
}
OF_HEADS = {"distribution", "structure", "range", "pair", "tendencies"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    word = word.strip(".,!?;:()[]{}\"'`“”‘’")

    previous = ""
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2].strip().lower()
        previous = previous.strip(".,!?;:()[]{}\"'`“”‘’")

    if word == "of" and previous in OF_HEADS:
        return None, 0.49
    if word in PAIR_WORDS or word.startswith(("两", "兩")):
        return None, 0.50
    if word in MATH_TERMS:
        return None, 0.32
    return None, 0.0

programs.sol:
"""A lexical detector for MOD and its extended forms.

The short piece 'mod' is strongest, 'mode' is next, and longer words
(model, module, modify, etc.) are weaker. Leading code punctuation does
not hide the word. A few corresponding Chinese/Cyrillic forms also fire.
Smaller responses recognize fragments (mo, od), formatting words, and
translations of mode/model. It remembers one token to recognize a split
mod + suffix and the linking word in mode/model/module + of.
This is a spelling-based approximation, not semantic understanding.
"""

READS = ()


def lexical_value(token):
    word = token.lstrip(" \t\r\n._-/\\(:<='")
    lower = word.lower()
    if lower in {"mod", "mods"}:
        value = 5.85 if lower == "mod" else 5.5
        if word.isupper():
            value = 5.0
        elif word[:1].isupper():
            value += 0.25
        if token.startswith("_") and word.islower():
            value -= 0.65
        return value
    if lower in {"mode", "modes"}:
        value = 4.1 if lower == "mode" else 3.45
        if token.startswith("_"):
            value -= 0.4
        if word.isupper():
            value += 0.8
        return value
    if lower.startswith(("model", "modèl", "modern")):
        return 0.85
    if lower.startswith("modif"):
        return 2.2
    if lower.startswith("module"):
        if lower == "modules" and token.startswith("_"):
            return 1.2
        return 1.7
    if lower.startswith(("modula", "modulat", "modulo")):
        return 3.25
    if lower.startswith("modulus"):
        return 2.65
    if lower.startswith("moderat"):
        return 1.5 if lower == "moderate" else 2.4
    if lower in {"modal", "modo", "moda", "moder"}:
        return 2.7
    if lower in {"format", "formats", "formatted", "formatting",
                 "formato"}:
        return 0.85 if token.startswith(" ") else 0.6
    if lower == "manner":
        return 0.46
    if lower in {"mo", "od", "ód", "од"}:
        return 0.7
    if lower in {"ode", "odes", "odal"}:
        return 0.6
    if word in {"モ", "모"}:
        return 1.85
    if word in {"修改", "模块"}:
        return 1.3
    if word == "模":
        return 6.0
    if word == "模式":
        return 3.0
    if word == "模型":
        return 0.8
    if lower == "мод":
        return 5.3
    if lower.startswith("модел"):
        return 0.55
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ""
    token = prefix.token_strings[-1]
    word = token.lstrip(" \t\r\n._-/\\(:<='").lower()
    if "�" in token:
        # A Chinese character can span byte-level tokens.
        token = prefix.text_prefixes[-1][-1:]
    value = lexical_value(token)
    # A root split from its suffix: mod + ified / ulate / ular / etc.
    if previous == "mod" and token[:1].isalpha():
        if word.startswith(("if", "ul")):
            value = 1.8
        elif word in {"al", "us", "s", "o"}:
            value = 1.45
    if token == " of":
        if previous in {"mode", "modes"}:
            value = 1.0
        elif previous in {"model", "models", "module", "modules"}:
            value = 0.25
    return (document, word), float(value)

programs.luna:
"""Recognize words naming a model, module, modification, or mode.

The strongest observed responses are to ``mode`` and the programming/math
shorthand ``mod``.  Model and module words are weaker, while ``manner`` and
the Chinese word for a mode get small, related predictions.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower()

    if "model" in token:
        value = 0.81
    elif "modul" in token:
        value = 1.62
    elif "modif" in token:
        value = 1.89
    elif "mode" in token or token == "模式":
        value = 3.42 if token != "模式" else 2.79
    elif "mod" in token:
        value = 5.22
    elif "manner" in token:
        value = 0.54
    else:
        value = 0.0
    return None, value

programs.haiku:
"""layers.0.mlp.down_proj:133 — a 'phrasal particle after an object' detector.

Fires on the word that comes right after an object pronoun (you, me, him, her, us, them,
it, and the -self forms) when that word is a particle or preposition or determiner, as in
"help you [with]", "guide you [through]", "break it [up]", "give me [a]", "show them [how]".
Weaker: after demonstratives and people nouns ("this [up]", "people [to]"). Also fires on
the particles "at" (about 0.7), "up"/"down"/"away" (about 0.5) and "out" (0.2) wherever they
occur. Everything else predicts 0.
"""

READS = ()

OBJECT_PRONOUNS = {"you", "me", "him", "her", "us", "them", "it",
                   "herself", "himself", "themselves", "yourself", "myself"}
WEAK_LEAD_WORDS = {"this", "that", "those", "there", "here", "one", "people", "students",
                   "everything", "things", "anyone", "everyone", "someone", "others"}
PARTICLES_AND_PREPOSITIONS = {"at", "up", "down", "out", "away", "off", "back", "through",
                              "to", "with", "on", "for", "in", "into", "over", "about",
                              "from", "by"}
DETERMINERS_AND_WH = {"the", "a", "an", "all", "some", "any", "both", "what", "how", "be",
                      "not", "ever", "more", "my", "his", "our", "its", "here", "there"}
FOLLOWER_WORDS = PARTICLES_AND_PREPOSITIONS | DETERMINERS_AND_WH


def word(token):
    # A whole word: the token starts with a space (so "us" inside "Perseus" doesn't count).
    return token[1:].lower() if token[:1] == " " else None


def step(carry, prefix, upstream):
    word_now = word(prefix.token_strings[-1])
    same_doc = len(prefix) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]
    word_before = word(prefix.token_strings[-2]) if same_doc else None

    value = 0.0
    if word_now in FOLLOWER_WORDS:
        weight = 1.0 if word_now in PARTICLES_AND_PREPOSITIONS else 0.6
        if word_before in OBJECT_PRONOUNS:
            value = 1.5 * weight
        elif word_before in WEAK_LEAD_WORDS:
            value = 0.3 * weight
    if value == 0.0:
        if word_now == "at":
            value = 0.7
        elif word_now in {"up", "down", "away"}:
            value = 0.5
        elif word_now == "out":
            value = 0.2
    return None, value

programs.sol:
"""A lexical/grammatical response to English prepositions, mainly 'by'.

Passive-verb + 'by' is usually positive, especially for representation,
production and support. Division and 'defined by' are negative exceptions.
A few noun + 'of' constructions and document-opening markers also respond.
These are category averages, not a dictionary of every collocation.
"""
import re

READS = ()

# Semantic families of words immediately preceding 'by'.
BY_FAMILIES = (
    (2.1, 'exhibited exemplified'),                         # giving examples
    (1.6, 'represented demonstrated illustrated shown evidenced reflected '
          'expressed displayed portrayed'),               # representation
    (1.5, 'supported covered helped aided facilitated offered'),
    (1.2, 'made done performed produced written published executed played '
          'collected received contributed powered manufactured processed '
          'completed'),                                   # production
    (-0.22, 'determined characterized specified bounded described given '
            'identified'),                                # specification
    (-0.3, 'asked appointed assigned designated'),          # requests/duties
)
BY_FAMILIES = tuple((v, frozenset(words.split())) for v, words in BY_FAMILIES)
PAST_PARTICIPLES = frozenset('''
made done written given shown driven taken held led taught sold found built
seen sent read struck understood paid broken run known born bought brought
caught chosen drawn eaten felt heard kept lost met put said thought won
'''.split())


def by_value(word, original):
    if word == 'served':
        return 2.45
    if word == 'defined':
        return -0.97
    if word in ('divide', 'divides', 'divided', 'dividing', 'division'):
        return -0.87
    if word in ('divisible', 'divisor', 'multiply', 'multiplying', 'step'):
        return -0.33
    if word == 'related':
        return -0.7
    if original in ('Posted', 'Created', 'Uploaded', 'Photo'):
        return -0.1
    for value, words in BY_FAMILIES:
        if word in words:
            return value
    if word.endswith('ed') or word in PAST_PARTICIPLES:
        return 0.67
    if word.endswith('ly'):
        return 0.56
    if word in ('out', 'up', 'on', 'in', 'to', 'for', 'at', 'upon'):
        return 0.65
    if word in ('is', 'are', 'was', 'were', 'them', 'you', 'us', 'this'):
        return 0.65
    return 0.22


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    match = re.search(r'([A-Za-z]+)$', tail)
    original = match.group() if match else ''
    word = original.lower()
    value = 0.0
    if token == ' by':
        value = by_value(word, original) if word else (0.13 if tail else -0.26)
    elif token in ('By', ' By'):
        value = 0.41
    elif token in ('BY', ' BY'):
        value = 0.23
    elif token == 'by':
        value = 0.18
    elif token == ' of':
        if word == 'result':
            value = -0.89
        elif word in ('results', 'outcome', 'consequence', 'effect', 'effects'):
            value = -0.35
        elif word in ('use', 'uses', 'help', 'properties', 'quality',
                      'characteristics', 'features', 'feature'):
            value = 0.4
    elif not tail and token in ('#', 'package'):
        value = 0.87 if token == '#' else 0.956
    return (doc, (tail + token)[-64:]), value

programs.haiku:
"""Scale and degree words. The component fires on the word that names an extreme or a
comparison of size, height, amount, speed, price or age: superlatives (highest, lowest,
largest, longest, fastest, best), comparatives (higher, lower, larger, faster), the
extremes high, low, max, minimum, maximal, minimal, huge and free. It fires most on
Chinese degree phrases: 很好 (very good), 最好 (best), 更多 (more), 很多 (many),
最大 (biggest), 太大 (too big), 最高 (highest), and on any other Chinese word built with
a degree marker (很, 太, 非常, 极, 较, 最, 更), except words where 更 or 最 is
not a degree marker (更新 update, 更改 change, 最后 last, 最近 recent). English more,
most, many, very and much do not fire, and nor do ordinary adjectives such as good or big.
"""

READS = ()

SUPERLATIVES = {
    "highest", "lowest", "largest", "biggest", "smallest", "longest", "shortest",
    "strongest", "weakest", "fastest", "widest", "oldest", "youngest", "earliest",
    "easiest", "hardest", "newest", "cheapest", "closest", "deepest", "poorest",
    "richest", "brightest", "hottest", "simplest", "fullest", "tallest",
}
BEST_LIKE = {"best", "worst", "greatest", "latest", "nearest", "optimal"}
COMPARATIVES = {
    "higher", "lower", "larger", "bigger", "smaller", "longer", "shorter", "stronger",
    "faster", "wider", "deeper", "heavier", "cheaper", "closer", "fewer", "easier",
    "younger",
}
EXTREMES = {
    "high", "low", "max", "maximum", "minimum", "maximal", "minimal", "free", "huge",
    "enormous", "immense", "高", "低",
}
CHINESE_PHRASES = {
    "很好", "很多", "很大", "很长", "很快", "很高", "很低", "很棒", "最好", "最大", "最高",
    "最低", "最多", "最新", "最小", "更多", "更高", "更大", "较多", "较高", "不少", "许多",
    "太大", "太多", "太高", "极高", "极大", "越来越多", "还不错", "不错", "挺好", "比较好",
    "尽快", "良好",
}
CHINESE_DEGREE_WORDS = {"很", "最", "非常", "较"}
CHINESE_DEGREE_MARKERS = "很太非常极较最更"
NOT_DEGREE = ("更新", "更改", "更换", "更是", "更加", "更为", "更具", "更有", "更要", "最后", "最近")


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in SUPERLATIVES or word.endswith("-free") or word == "-free":
        value = 2.0
    elif word in BEST_LIKE:
        value = 0.8
    elif word in ("high", "higher", "高"):
        value = 1.5
    elif word in EXTREMES or word in COMPARATIVES:
        value = 1.0
    elif word in CHINESE_PHRASES:
        value = 3.0
    elif word in CHINESE_DEGREE_WORDS:
        value = 1.2
    elif len(word) <= 4 and any(c in word for c in CHINESE_DEGREE_MARKERS) and not word.startswith(NOT_DEGREE):
        value = 2.0
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Mostly a detector of literal ampersands and character-encoding debris.

Predict large positive values for single ampersands, smaller ones for &&, &=,
and mathematical alignment. Secondary cues are byte/Unicode escapes, mojibake,
NULs, C1 controls, certain unfinished UTF-8 characters, and question marks.
Keep 120 characters of context to recognize TeX and adjacent/split escapes;
reset that context at document boundaries. All other tokens predict zero.
"""
import re

READS = ()
# Vocabulary byte tokens, distinguished because each decodes alone as "�".
LATIN1_LEAD_BYTE = frozenset({126, 2139})  # C2, or space followed by C2
PRIVATE_USE_LEAD_BYTE = 170    # EE: start of a BMP private-use character
MATH_COMMAND = re.compile(r"\\(?:frac|begin|partial|sqrt|Def|sum|int|mathrm|text)")
BYTE_ESCAPE_END = re.compile(r"\\x[0-9a-fA-F]{1,2}$")


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    text = token.strip()
    value = 0.0
    if '&' in text:
        if '&&' in text:
            value = 0.1
        elif '&=' in text:
            value = 0.25
        elif '&#' in text:
            value = 1.3
        elif text == '&':
            value = 1.0
            if MATH_COMMAND.search(tail):
                value = 0.35 if token.startswith(' ') else 0.6
        elif text.endswith('&'):
            value = 0.8
        else:
            value = 0.65
    elif '＆' in text:
        value = 0.7
    elif text.startswith('\\x'):
        value = 0.32
        if text.startswith('\\xe'):
            value = 1.1 if BYTE_ESCAPE_END.search(tail) else 1.75
        elif text.startswith('\\xc'):
            value = 0.65
        elif text.startswith('\\xa'):
            value = 0.23
    elif tail.endswith('\\') and text in ('xe', 'xc'):
        value = 0.41 if text == 'xe' else 0.30
    elif text.startswith('\\u'):
        value = 0.42
    elif text == "\\'":
        value = 0.75
    elif text in ('â', 'Â'):
        value = 0.48
    elif text == 'Ã':
        value = 0.9
    elif '\x00' in text:
        value = 0.73
    elif any('\x80' <= char <= '\x9f' for char in token):
        value = 0.7
    elif prefix.token_ids[-1] in LATIN1_LEAD_BYTE:
        value = 0.6
    elif prefix.token_ids[-1] == PRIVATE_USE_LEAD_BYTE:
        value = 0.55
    elif token and set(token.lstrip(' ')) == {'?'}:
        if len(text) > 1:
            value = 0.47
        elif token.startswith(' '):
            value = 0.24
    return (document, (tail + token)[-120:]), value

programs.luna:
"""A modest positive pulse for ampersands and escape-like text markers.

The sampled strong responses cluster on ampersands, including HTML
entities, with some on Unicode/byte escape fragments and NUL characters.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
