programs.sol:
"""Local English quantity and time phrases.

`at least` is positive; restricted counts and occasions are negative.
Numbers one and two are most sensitive. A few smaller rules recognize
limiting and contrastive clause openings. Unrecognized tokens are near
zero. Only the previous two tokens are remembered, within each document.
"""
READS = ()
NUMBERS = set('one two three four five six seven eight nine ten eleven '
              'twelve twenty thirty forty fifty hundred thousand million'.split())
PRONOUNS = set('i you he she it we they this that'.split())
ORDINALS = set('first last next second third fourth fifth'.split())
DISTRIBUTIVE = set('any every each all'.split())

# Common modifiers of an occasion or a duration, ordered from strongest.
TIME_MODIFIERS = (
    (-2.2, {'first', 'last', 'next', 'only'}),
    (-1.7, {'any', 'one', 'second', 'third', 'other'}),
    (-1.5, {'long', 'longer', 'short', 'shorter', 'hard', 'difficult',
            'great', 'best', 'single', 'final', 'earliest', 'fastest'}),
    (-1.28, DISTRIBUTIVE | {'at'}),
    (-1.0, {'real', 'full', 'limited', 'good', 'no', 'total', 'more',
            'shortest', 'past', 'least', 'remaining', 'consecutive'}),
    (-0.9, {'certain', 'particular', 'given', 'different', 'discrete'}),
    (-0.6, {'of', 'same', 'that', 'some', 'a'}),
    (-0.13, {'the', 'this'}),
)

# Strength of a restriction on a count, before number-size scaling.
COUNT_MODIFIERS = (
    (1.5, {'only'}),
    (1.2, {'no'}),
    (1.0, {'just', 'exactly'}),
    (0.8, {'first', 'last', 'other'}),
    (0.7, DISTRIBUTIVE | {'least', 'most', 'another', 'next'}),
    (0.5, {'than', 'some', 'best', 'not'}),
    (0.17, {'a'}),
)


def phrase_value(raw, previous, before):
    w, p, b = (s.strip().lower() for s in (raw, previous, before))
    if w == 'least':
        if p == 'at':
            return 1.1 if previous.strip()[:1].isupper() else 1.32
        if p == 'very' and b == 'the':
            return 1.15
        return 0.08 if p == 'the' else 0.43 if p == 'not' else 0.23
    if w in {'time', 'times', '-time', '_time'}:
        if w == 'times':
            if p in {'all', 'many', 'several', 'more', 'few', 'of'}:
                return -1.1 if p == 'all' else -0.5
            if p in NUMBERS:
                return -0.3
        if w in {'-time', '_time'} and p in {'real', 'full', 'half', 'part', 'one'}:
            return -1.15 if p == 'one' else -0.34 if p == 'part' else -0.7
        if p in {'the', 'this', 'that', 'a'} and b == 'at':
            return -1.5 if p == 'a' else -0.94
        value = next((v for v, words in TIME_MODIFIERS if p in words), -0.36)
        return value * (0.5 if w == 'times' else 1.0)
    if w in NUMBERS | {'ones', 'half'}:
        scale = (1.0 if w in {'one', 'two'} else
                 0.6 if w in {'three', 'four', 'ones', 'half'} else
                 0.4 if w in {'five', 'six', 'seven', 'eight', 'nine'} else 0.2)
        strength = next((v for v, words in COUNT_MODIFIERS if p in words), 0.03)
        if p == 'all' and w in {'one', 'two'}:
            strength = 0.3
        return -strength * scale
    if w in {'way', 'ways', 'place'}:
        return (-1.08 if p == 'only' else -0.5 if p in {'no', 'other', 'long'}
                else -0.45 if p in ORDINALS | {'best', 'better', 'easiest'} else -0.06)
    if w == 'once' and p in {'only', 'just', 'exactly', 'most', 'least', 'at'}:
        if p == 'only':
            return -1.7
        if p in {'just', 'exactly'}:
            return -0.8
        return -0.22 if p == 'at' else -0.45
    if w == 'again' and p == 'once':
        return -0.62
    if w in {'if', 'when'} and p in {'only', 'even', 'especially', 'except'}:
        return -0.78 if p == 'only' else -0.25
    if p == 'only':
        if w in {'few', 'little', 'small', 'slightly', 'partially', 'partly', 'other'}:
            return -0.9
        if w in {'a', 'an', 'in', 'by', 'because'}:
            return -0.33
        if w in {'this', 'that', 'to'}:
            return 0.4 if w != 'to' else 0.13
    if p == 'least':
        if w in PRONOUNS | {'of', 'the'}:
            return 0.56
        if w in {'a', 'an', 'to', 'as', 'not', 'in', 'for', 'about'}:
            return 0.33
    if w in PRONOUNS:
        if p == 'but':
            return 0.5 if w == 'this' else 0.36 if w == 'that' else 0.27
        if p in {'once', 'when'}:
            return -0.26 if p == 'once' else -0.15
        if p in {'as', 'for', 'so', 'now'}:
            return 0.13
    if w == 'of' and p in {'any', 'best', 'most', 'percent', 'degree', 'ratio'}:
        return 0.4 if p in {'any', 'best'} else 0.16
    if w == 'to' and p in {'limited', 'restricted', 'best', 'better', 'good', 'sure',
                           'hard', 'difficult', 'harder'}:
        return 0.59 if p in {'limited', 'restricted', 'best'} else 0.28
    return 0.001


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, before = '', ''
    else:
        _, previous, before = carry
    return (doc, token, previous), float(phrase_value(token, previous, before))

programs.luna:
"""A small lexical proxy for sparse time/count activations.

The harvested strong responses often occur on time and small-number words.
This rule gives least a positive value, the time/count words negative values,
and leaves other tokens at zero; context still changes the real response.
"""
READS = ()

SMALL_NUMBERS = {
    "one", "two", "three", "four", "five", "six", "seven",
    "eight", "nine", "first", "second", "third",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    word = word.strip(" \t\r\n.,:;!?()[]{}\"'`-—–")

    if word == "least":
        value = 0.32
    elif word in {"time", "times"}:
        value = -0.29 if word == "time" else -0.23
    elif word in {"one", "two"}:
        value = -0.24
    elif word in SMALL_NUMBERS:
        value = -0.17
    else:
        value = 0.0
    return None, value

"""Predict a strong negative cue for Greek omicron and weaker language cues.

Other Greek letters and non-ASCII letters get smaller responses; do/does/did
get one when they follow an open ``how ...`` phrase. The estimates are damped
to avoid overpredicting the component's size.
"""
import re
import unicodedata

READS: tuple[str, ...] = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    old_document, context = carry or (document, "")
    if document != old_document:
        context = ""

    token = prefix.token_strings[-1].strip()
    lower = token.lower()

    if token in {"ο", "ό"}:
        value = -8.5
    elif token in {"Ο", "Ό"}:
        value = -4.5
    elif token == "ου":
        value = -4.5
    elif any("GREEK" in unicodedata.name(ch, "") for ch in token):
        value = -1.0
    elif lower in {"do", "does", "did"} and re.search(
        r"\bhow\b[^?.!;:\n]{0,60}$", context, re.IGNORECASE
    ):
        value = -1.1
    elif any(ord(ch) > 127 and ch.isalpha() for ch in token):
        value = -0.3
    else:
        value = 0.0

    context = (context + prefix.token_strings[-1])[-120:]
    return (document, context), value * 0.6

programs.sol:
"""Approximate a local second-person signal with grammatical word classes.

The main positive pulse is on 'you', especially after if/when/unless or
can/could. Prepositions and object-verb cues reduce it. Smaller signed
pulses continue into following auxiliaries and verbs; a conditional
clause strengthens some of those continuations. Minor rules cover
'your', conditional subjects, and a few Chinese/Vietnamese forms of
'you'. Unmatched tokens get zero. Only two previous tokens are kept,
and that history resets at document boundaries.
"""
READS = ()

CONDITIONS = {'if', 'when', 'unless'}
CLAUSE_LINKS = {'because', 'since', 'once', 'until', 'whether'}
PREPOSITIONS = set('to for of from with by in on at about'.split())
OBJECT_CUES = set('help assist support guide inform thank see hope'.split())
TRANSFER_OR_PERMISSION = set(
    'give gives tell tells show shows let allow allows'.split()
)
MODALS = set('can could will would should shall may might must'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, before = '', ''
    else:
        prev, before = carry[1:]
    token = prefix.token_strings[-1].strip()
    word, p, b = token.lower(), prev.lower(), before.lower()
    value = 0.0
    if word == 'you':
        value = 0.80
        if p in CONDITIONS:
            value = 2.65
        elif p in {'can', 'could'}:
            value = 3.45 + 0.30 * prev[:1].isupper()
        elif p in CLAUSE_LINKS:
            value = 1.65
        elif p in PREPOSITIONS:
            value = 0.30
        elif p in OBJECT_CUES:
            value = -0.20 if p == 'thank' else 0.15
        elif p in TRANSFER_OR_PERMISSION:
            value = 1.30
        elif p in {'how', 'why', 'where', 'then', 'but', 'so'}:
            value = 1.25
        elif p in {'do', 'did'}:
            value = 1.55 if p == 'do' else 1.0
            if prev[:1].isupper():
                value = 0.45
        elif p in {'are', 'have'}:
            value = 0.40
            if prev[:1].isupper():
                value = -0.70 if p == 'are' else 0.0
        elif p in {'sure', 'want', 'need', 'or'}:
            value = 0.30
        value += 0.12 * token[:1].isupper()
        if b in MODALS or b == 'to':
            value -= 0.30
        elif b in {'how', 'why', 'what', 'where'}:
            value += 0.35
    elif p == 'you':
        if word in {'can', 'could', 'cannot'}:
            value = 1.05 if word == 'can' else 1.23
            if b in CONDITIONS:
                value += 0.40
            elif prev[:1].isupper():
                value += 0.20
        elif word in {'are', 'will', "'re", '’re', "'ll", '’ll'}:
            value = -0.40 + 0.22 * (b in CONDITIONS)
        elif word in {"'ve", '’ve', 'like'}:
            value = -0.60
        elif word in {'would', 'must', 'do', 'had', 'were'}:
            value = 0.45
        elif word in {'should', 'might', 'don'}:
            value = 0.27
        elif word in {'get', 'go', 'take', 'give', 'provide', 'look'}:
            value = 0.75
        elif word in {'think', 'feel', 'wish', 'believe', 'expect'}:
            value = -0.40
        elif word in {'want', 'know', 'need'}:
            value = 0.60 if word == 'know' else 0.35
        elif word in {'to', 'use', 'make', 'read', 'tell'}:
            value = 0.16
        if b in CONDITIONS and word in {'have', 'want', 'know', 'need'}:
            value += 0.65
    elif b == 'you' and p in {'can', 'could'} and word in {"'t", '’t'}:
        value = 0.70
    elif word == 'your':
        value = 0.80 if p in CONDITIONS else 0.10
    elif word in {'i', 'we', 'they', 'he', 'she'} and p in CONDITIONS:
        value = 0.40 if word == 'we' else 0.20
    elif word in {'你', '你们', '你們', 'bạn'}:
        value = 0.70
    return (doc, token, prev), float(value)

programs.haiku:
"""Second-person "you" detector (layer 0, MLP down_proj, component 142).

What it does: this component fires on the English second-person pronoun "you"
("You", "YOU" too), and weakly on a few other-language words for "you". How strongly
it fires depends on the word just before "you" in the same document:

* "you" as the subject of a clause opened by a conditional or temporal word
  ("if you", "when you", "unless you", "once you"), or after "can"/"could", fires
  strongest (about 2.7).
* "you" after an ordinary clause linker (", you", "and you", "that you", "so you",
  "how you", "then you") fires moderately (about 1.1).
* "you" as an object, after verbs or prepositions that take one ("thank you",
  "help you", "for you", "with you"), or in "are you" questions, is about zero.
* Otherwise "you" fires at about 0.9. A "you" that already occurred earlier in the
  same document fires a bit less.
* The modal "can"/"could" right after "you" also fires.

Everything else predicts 0. Document boundaries reset the context, as in the model.
"""

READS: tuple[str, ...] = ()

YOU = {" you", " You", "You", "you", " YOU", "YOU"}
YOU_OTHER = {"你", "你们", "你們", "您", " vous", " você", " bạn", "あなた", " puede", " можете"}
YOUR = {" your", " Your"}
OPENERS = {" if", " If", "If", " when", " When", "When", " unless", " once", " Once",
           " until", " since", " because", " Because", " Can", " can", " Could", " could"}
LINKERS = {",", " and", " that", " so", " how", " where", " then", " but", " what", " which",
           " whether", " as", " why", " while", " do", " did", " would", " allows", " gives",
           " give", " tell", " tells", " allow"}
OBJECT_FRAMES = {"Thank", " Thank", " thank", " help", " for", " with", " to", " are", "Are", " Are",
                 " love", " guide", " hope", " assist", " advise", " feel", " support"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    # carry: how many "you" words came earlier in this document
    seen = carry[1] if carry is not None and same_doc else 0
    if tok in YOU:
        if prev in OPENERS:
            value = 2.7
        elif prev in OBJECT_FRAMES:
            value = 0.0
        elif prev in LINKERS:
            value = 1.1
        else:
            value = 0.9
        if seen:
            value *= 0.8
        return (prefix.document_ids[-1], seen + 1), value
    new = (prefix.document_ids[-1], seen)
    if tok in (" can", " could") and prev in YOU:
        return new, 1.2
    if tok in YOU_OTHER:
        return new, 0.6
    if tok in YOUR:
        return new, 0.1
    return new, 0.0

programs.sol:
"""Approximate a small-piece-of-a-word response, strongest for an unspaced s.

ASCII letters get a larger value when continuing alphabetic text; uppercase
letters mainly respond inside uppercase sequences. Spacing, escapes, and
whether the preceding piece is itself one letter modify that response.
The constants also distinguish common English suffixes, several non-Latin
letter classes and grammatical endings, and bare punctuation boundaries.
These are coarse training-derived amplitudes, not a full spelling model.
Only the preceding token is remembered, with resets between documents.
"""
import unicodedata

READS = ()
UNCOMMON_ENGLISH_LETTERS = frozenset('jqkvwxyz')
RUSSIAN_SIGNS = frozenset('ъь')
RUSSIAN_EXTRA_VOWELS = frozenset('ёэюя')
RUSSIAN_DIGRAPH_CONSONANTS = frozenset('жхцчшщ')
ENGLISH_SUFFIXES = frozenset(('ed', 'er', 'ing', 'ly'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    s = prefix.token_strings[-1]
    last = previous[-1:]
    inside_word = last.isalpha() or last == '\ufffd'
    value = -0.001
    if len(s) == 1 and s.isascii() and s.isalpha():
        # A neighboring Greek symbol or ideograph is not part of a Latin word.
        if last and not last.isascii() and last != '\ufffd':
            name = unicodedata.name(last, '')
            inside_word = name.startswith(('LATIN', 'CYRILLIC'))
        if s.islower():
            value = -0.05 if s in UNCOMMON_ENGLISH_LETTERS else 0.03
            if inside_word:
                value += 0.37 if s in UNCOMMON_ENGLISH_LETTERS else 0.51
                if len(previous.strip()) == 1 and last.isascii():
                    value -= 0.13
            elif last.isdigit():
                value += 0.07
            if s == 's':
                value += 0.45
            elif s == 'e':
                value += 0.15
        else:
            value = -0.08 if s.lower() in UNCOMMON_ENGLISH_LETTERS else -0.025
            if last.isupper():
                value += 0.50
                if len(previous.strip()) == 1:
                    value -= 0.17
            elif inside_word:
                value += 0.10
            if s == 'S':
                value += 0.18
        if last == '\\':
            value = -0.025
    elif len(s) == 1 and s.isalpha():
        name = unicodedata.name(s, '')
        if name.startswith('CYRILLIC'):
            if s.islower():
                value = 0.47 if '\u0430' <= s <= '\u044f' else 0.0
                if s in RUSSIAN_SIGNS or s in RUSSIAN_EXTRA_VOWELS:
                    value = 0.0
                elif s in RUSSIAN_DIGRAPH_CONSONANTS or s in 'ый':
                    value = 0.25
            else:
                value = 0.26 if inside_word else 0.01
        elif name.startswith('ARABIC'):
            # The basic Arabic alphabet, rather than Persian extensions.
            value = 0.47 if '\u0621' <= s <= '\u064a' else 0.04
            if s in 'ةى':
                value = 0.16
        elif name.startswith('THAI'):
            value = 0.52
            if 'SARA' in name:
                value = 0.05
        elif s == '了':  # Chinese completed-action/change-of-state particle.
            value = 0.88
        elif s == '得':  # Chinese complement marker.
            value = 0.51
        elif s == 'い':  # Japanese adjective ending.
            value = 0.52
    elif s in ENGLISH_SUFFIXES and inside_word:
        value = 0.12
    elif s in ('\"', "'"):
        value = 0.025 if last.isalpha() else 0.22
        if last == 'f' and not previous[-2:-1].isalpha():
            value = 0.56  # Python f-string opening.
    elif s == ';' and previous in ('amp', 'lt', 'gt', 'quot', 'apos'):
        value = 0.55  # End of a named HTML character entity.
    elif s == '-':
        value = 0.68 if last.isspace() or not last else 0.04
        if last and not last.isalnum() and not last.isspace():
            value = 0.21
    elif s == '_':
        value = 0.025 if last.isdigit() else 0.20
    return (doc, s), float(value)

programs.haiku:
"""Layer-0 MLP unit 143 (down_proj): a letter that continues a split word.

The tokenizer often cuts a word into pieces, and this unit fires on a single-letter
piece that carries on the word started by the token before it, with no space or
punctuation between them: "analy|t|ically", "RE|s", "Initial|s", "Fox|e", "OEIC|s".
Strength by letter: a plural or possessive "s" is strongest; common lowercase
Latin letters about half; capitals about a third; Cyrillic, Arabic and Thai letters
about 0.4; accented Latin letters and Greek are ~0. A "-" that opens a line
(a bullet) fires a little too. Everything else, including CJK characters (each a
whole word), stays at 0.
"""

import unicodedata

READS = ()

NONLATIN_LETTER_SCRIPTS = {"CYRILLIC", "ARABIC", "THAI"}


def _script(ch):
    try:
        return unicodedata.name(ch).split()[0]
    except ValueError:
        return ""


def _letter_strength(ch):
    if ch.isascii():
        if ch == "s":
            return 1.0
        return 0.5 if ch.islower() else 0.3
    if _script(ch) in NONLATIN_LETTER_SCRIPTS:
        return 0.4
    return 0.0


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2]
    if cur == "-" and "\n" in prev:
        return None, 0.65
    if len(cur) != 1 or not cur.isalpha():
        return None, 0.0
    if prev and prev[-1].isalpha() and _script(prev[-1]) == _script(cur):
        return None, _letter_strength(cur)
    if cur == "s":
        return None, 0.6
    return None, 0.0

programs.luna:
"""Predicts a positive signal on one-letter word continuations, especially s/e/d."""
import unicodedata
from functools import lru_cache

READS = ()


@lru_cache(None)
def _script(char):
    try:
        name = unicodedata.name(char)
    except ValueError:
        return ""
    for script in ("LATIN", "CYRILLIC", "ARABIC", "THAI"):
        if script in name:
            return script
    return ""


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    previous = None
    if carry is not None and carry[0] == doc:
        previous = carry[1]

    value = 0.0
    if len(text) == 1 and text.isalpha():
        if text == "了":
            value = 0.84
        elif previous and previous.isalpha():
            current_script = _script(text)
            previous_script = _script(previous)
            if current_script and current_script == previous_script:
                if text.isascii() and text.islower():
                    value = {"s": 0.95, "e": 0.75, "d": 0.70}.get(text, 0.50)
                elif text.isascii() and text.isupper():
                    value = 0.31
                elif current_script != "LATIN":
                    value = 0.42
    elif text in ("-", "–", "—") and previous and previous.isspace():
        value = 0.24

    return (doc, text[-1:] if text else ""), value

programs.sol:
"""Sparse lexical responses: traffic, reasoning tags, and GUI/web code.

The strongest negative cue is 交通, the Chinese/Japanese word for
traffic. Transport and congestion words are weaker negative cues.
Reasoning tags and a few GUI API families have distinct responses.
GitHub after :// has a negative response. Unmodeled
lexical variation is left at zero, with a small document-start bias.
Conversation boundaries also depend on the previous token or document start.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous = '' if start else carry[1]
    text = prefix.token_strings[-1]
    word = text.strip()
    lower = word.lower()

    if word == '交通':
        value = -1.33
    elif word == '交通运输':
        value = -0.95
    elif word == '道路交通':
        value = -0.8
    elif word == '交通事故':
        value = -0.27
    elif '交通' in word or word in ('出行', '拥堵', '路况'):
        value = -0.55
    elif word == '拥挤':
        value = -0.3
    elif word in ('道路', '公路', '路段'):
        value = -0.12
    elif lower == 'transportation':
        value = -0.29
    elif lower.startswith('congest'):
        value = -0.18
    elif lower in ('commuter', 'commuters', 'commuting'):
        value = -0.13
    elif lower in ('traffic', 'transport', 'travel', 'commute'):
        value = -0.06
    elif word == 'of' and previous.lower() == 'transportation':
        value = -0.22

    elif word == '<think>':
        value = 0.365
    elif word == '</think>':
        value = -0.18
    elif word == '<tool_response>':
        value = -0.086
    elif word == '<|im_start|>':
        value = -0.121 if start else 0.022
    elif word == '<|im_end|>':
        if previous == '</tool_response>':
            value = 0.1
        else:
            value = -0.045 if previous in ('.', '?') else 0.02

    elif word == '.innerHTML':
        value = 0.58
    elif word.lstrip('.') in ('innerHTML', 'InnerHTML', 'textContent'):
        value = 0.38
    elif word in ('.preventDefault', '.stopPropagation'):
        value = -0.58
    elif word == '.addEventListener':
        value = -0.18
    elif word in ('.ActionListener', '.ActionEvent', '.KeyEvent'):
        value = -0.62
    elif word == 'ActionListener':
        value = -0.45
    elif word in ('addPreferredGap', 'addContainerGap'):
        value = -0.85
    elif word == '.awt':
        value = -0.48
    elif word in ('.swing', '.JButton', '.JTextField', '.addActionListener'):
        value = -0.2
    elif word == 'github' and previous.endswith('://'):
        value = -0.28
    else:
        value = -0.015 if start else 0.0
    return (doc, word), value

"""Approximate a hyphenated-word signal from token shapes and local text.

The largest response is to a hyphen fused with letters. It is smaller for
later hyphens in a compound and for common English prefixes; age phrases
ending in '-old' are a special weak case. Bare hyphens between word parts
are stronger than bullets after whitespace. A following letter fragment
gets a small echo. Case, length and path context adjust the estimate.
Other tokens are zero apart from a few related standalone separators.
All numbers are rounded estimates from training activations.
"""
READS = ()
NEGATING = {'non', 'anti'}
PREFIXES = {'pre', 'post', 'co', 're', 'multi', 'self'}
MODIFIERS = {'well', 'long', 'short', 'high', 'low', 'half', 'cross'}
AGE_UNITS = {'year', 'month', 'week', 'day'}
SEPARATORS = {'_': 0.54, ' _': 0.21, '‐': 1.04, '–': 0.24, '-\n': 0.15}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, word, path = '', '', False
    else:
        _, previous, word, path = carry
    token = prefix.token_strings[-1]
    last = previous[-1:]
    value = 0.0

    if token == '-':
        if not previous:
            value = -1.45
        elif last.isspace():
            value = 0.04
        elif last.isalpha():
            value = 1.22 - 0.24 * min(word.count('-'), 3)
        elif last.isdigit():
            value = 1.05 - 0.20 * min(word.count('-'), 2)
        else:
            value = 0.54
    elif token.startswith('-') and token[1:].isalpha():
        value = 2.32 + 0.10 * token[1].isupper() + 0.30 * path
        value -= 0.06 * min(max(len(token) - 3, 0), 8)
        if '-' in word:
            value -= 1.06
        elif word.lower() in NEGATING:
            value -= 1.14
        elif word.lower() in PREFIXES:
            value -= 0.61
        elif word.lower() in MODIFIERS:
            value -= 0.66
        elif word.isdigit():
            value -= 0.20
        if token == '-old' and word.lower().split('-')[-1] in AGE_UNITS:
            value = -0.45
        if not previous:
            value = 0.3
    elif token == ' -':
        if last.isalpha():
            value = 0.50
        elif last.isdigit():
            value = 0.37
        elif last.isspace():
            value = 0.12
        else:
            value = 0.23
    elif token in SEPARATORS:
        value = SEPARATORS[token]
    elif token in {'-(', '-[', '-{', '-\\'}:
        value = 0.8
    elif token in {')-', ']-', '}-'}:
        value = 0.43
    elif token.strip() == '---':
        value = 0.25
    elif token.isalpha() and previous.startswith('-'):
        if previous == '-':
            value = 0.33
        elif previous[1:].isalpha():
            value = 0.14 if previous[1].isupper() else 0.25

    # Track the connected word and whether its surrounding chunk has a slash.
    for character in token:
        if character.isspace() or character in '"\'<>;(){}':
            path = False
        elif character in '/\\':
            path = True
        if character.isalnum() or character == '-':
            word = (word + character)[-80:]
        else:
            word = ''
    return (doc, token, word, path), float(value)

programs.haiku:
"""Joiner-dash detector for layers.0.mlp.down_proj:146.

The component fires on a dash that joins two pieces of a word or identifier:
  * a hyphen glued to the word after it ("-plugin", "-client", "-content"): strong, about 2;
  * a bare hyphen right after a word or digit ("COVID -19", "E - Verify"): about 1;
  * a Unicode hyphen (U+2010) or a standalone underscore: about 0.6 to 1;
  * a hyphen after a space (" -") is weak, about 0.3.
Line-start bullets ("-" after a newline), "--", "->", "---", en dashes and the
other punctuation are near 0. On all other tokens it stays silent.
"""

READS = ()

STRONG = 2.05      # hyphen glued to a following letter or digit
BARE = 1.05        # lone "-" after a word or digit
SPACED = 0.3       # " -" with a leading space
UNICODE = 1.05     # U+2010 hyphen
UNDERSCORE = 0.6   # lone "_"


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if tok == "‐":
        return carry, UNICODE
    if tok == "_":
        return carry, UNDERSCORE
    if tok == "-":
        # a bullet at line start (after a newline or nbsp) is not a joiner
        if prev == "" or prev[-1:].isspace():
            return carry, 0.0
        return carry, BARE
    if tok == " -":
        return carry, SPACED
    if len(tok) > 1 and tok[0] == "-" and (tok[1].isalpha() or tok[1].isdigit()):
        return carry, STRONG
    return carry, 0.0

"""Effect-verb detector for layers.0.mlp.down_proj:147.

Fires on the verb of a clause that provides, creates, helps, or changes the amount or rate of
something ("can help", "to provide", "increase", "improve", "inhibit", "slow"), mostly in
expository, technical or health prose. It is strongest on the core verbs, weaker on the
related ones (block, reduce, keep, ...), and about 1.4x stronger after a modal or "to"
("can improve", "to help"). It is weaker when the word is a noun after a determiner
("the increase", "with their help"), as in noun uses and in code. Every other token predicts 0.
