CORE = {"provide", "help", "improve", "increase", "create", "enhance", "inhibit", "impair",
        "slow", "boost", "stimulate", "activate"}
# Related: verbs of lowering, blocking or releasing something (weaker).
RELATED = {"block", "supply", "strengthen", "reduce", "decrease", "stay", "keep", "promote",
           "accelerate", "restore", "release", "prevent"}
MODALS = {"can", "could", "may", "will", "would", "to", "cannot", "might", "must"}
DETERMINERS = {"the", "a", "an", "their", "its", "his", "her", "my", "your", "our", "with", "of"}
SUFFIXES = ("", "s", "es", "d", "ed", "ing", "ion", "ment", "er", "ers")


def lemma(word):
    """The core or related verb a word is an inflection of ('creating' -> 'create'), else ''."""
    for suffix in SUFFIXES:
        if suffix and not word.endswith(suffix):
            continue
        stem = word[: len(word) - len(suffix)]
        for candidate in (stem, stem + "e"):
            if candidate in CORE or candidate in RELATED:
                return candidate
    return ""


