    words = [s.strip().lower() for s in prefix.token_strings[-2:]]
    word = words[-1]
    previous = words[-2] if len(words) > 1 else ""
    verb = lemma(word)
    if verb in CORE:
        value = 0.5
    elif verb in RELATED:
        value = 0.25
    else:
        return None, 0.0
    if previous in MODALS:
        value *= 1.4
    if previous in DETERMINERS:
        value *= 0.4
    return None, value

