# Calibrated responses for especially strong mathematical word families.
MATH_FORMS = {
    'polynomial': -2.90, 'exponential': -2.60, 'exponentially': -2.40,
    'quadratic': -2.12, 'cubic': -2.02, 'linear': -1.76,
    'nonlinear': -1.72, 'equation': -1.78, 'formula': -1.30,
    'algorithm': -1.06, 'recursive': -1.23, 'recursion': -0.83,
    'logarith': -1.80, 'coefficient': -0.89, 'fraction': -0.81,
    'decimal': -0.77, 'exponent': -0.72, 'proportional': -1.05,
}

