    (-0.69, '''calculate calculated calculations mathematical derivative
        geometric orthogonal calculus quaternion oscill'''),
    (-0.54, '''calculation calculating proportion correlation hypothesis
        regression inverse approximation inequality factorial cosine gradient
        empirical deviation estimation recurrence fractional permutation
        encryption encrypted pixel rectangular fluorescence blockchain'''),
    (-0.30, '''algebra rational irrational matrix curve probability differential
        perpendicular statistical binary percent percentage theorem particle
        tangent slope metric estimate estimated diagonal cylindrical
        manifold finite computation computational geometry polygon curvature'''),
    (-0.46, '''protein molecule glucose polymer magnetic molecular neutron
        electromagnetic cortisol calcium hydrogen kinetic kinetics calories
        calorie antioxidant enzyme peptide mitochondrial antibody antibiotics
        fungi collagen vaccination pathogens nanoparticles metabol metabolic
        infection virus viral insects'''),
    (-0.86, '''photon quantum semiconductor gravitational hormone bacterial entropy
        bacteria waveform stochastic fibonacci'''),
    (-1.12, 'microbial gaussian'),
    (-0.16, 'expression index graph compute math'),
    # Recognizable technical fragments, not arbitrary token ids.
    (-2.85, 'ynomial ynomials'),
    (-2.60, 'ponential'),
    (-1.85, 'adratic'),
    (-0.80, 'omorphic orphism icrobial'),
    (-0.65, 'abolic oidal adecimal ivative ellipt polation'),
    (-0.43, '''equ pol cub quadr calcul fract invers
        ometric etric agnetic olecular gebra'''),
