"""A sparse syntax-introducer detector.

Escapes, markup delimiters/entities, format-percent signs, and documentation
annotations get negative responses. Document-local escape counts and a short
suffix distinguish encoded text or markup from math and ordinary prose.
Small, word-specific activations are intentionally predicted as zero.
"""
import re

READS = ()
ATTRIBUTE = re.compile(r'\b(?:class|id|href|src|name)\s*=')
MATH = re.compile(r'\\(?:frac|left|right|sum|int|begin|math|sqrt|nabla)')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0, 0)
    _, recent, previous, lines, hexes = carry
    token = prefix.token_strings[-1]
    s = token.strip()
    spaced = token.startswith(' ')
    text = recent[-200:]
