        encoded = lines > 1 and not (math and not hexes)
        if s.startswith('\\x'):
            value = (-3.2 if lines else -1.8) if s == '\\x' else -1.8
        elif s.startswith('\\u'):
            value = -1.0
        elif s and not s.strip('\\'):
            if len(s) > 1:
                value = -1.35 if encoded else -1.0
            elif encoded:
                value = -1.33 if spaced else -0.79
                if hexes > 2:
                    value = -3.3 if spaced else -2.1
            else:
                value = -0.6 if spaced else (-0.12 if math else -0.35)
        elif '\\\\' in s:
            value = -0.95
        elif s.endswith('\\') and encoded:
            before = s[:-1]
            if before.endswith(('):', ').')):
                value = -0.65
            elif before.endswith(')'):
                value = -0.55
            elif before in (';', ':', '.', ',', "'", '\\"'):
                value = -0.3
            elif before == '{':
                value = -0.45 if spaced else -0.21
        elif s == "\\'":
            value = -0.5
        elif '\\<' in s:
            value = -0.5
    elif any(c in s for c in '<%@&') or s in ('="', "='", 'class'):
        closes = text.count('</')
        attributes = bool(ATTRIBUTE.search(recent))
        digit = previous[-1:].isdigit()
        if s.endswith('</'):
            value = -0.9 if spaced else -0.7
        elif token.endswith('<') and s.count('<') == 1:
            if '>' in s or any(q in s for q in '\"\''):
                value = -2.1 if closes else -1.4
            elif closes:
                value = -3.0 if attributes else -2.3
                if previous.endswith('/'):
                    value -= 0.6
                if not spaced:
                    value *= 0.65
            elif previous and previous.isspace():
                value = -2.5 if attributes else -1.2
            elif re.search(r'\n[^\n]{0,20}(?:///|\*)\s*$', text):
                value = -1.6
            else:
                value = -0.1
        elif re.fullmatch(r'<[a-z][a-z0-9]*', s) and closes:
            value = -0.65
        elif s == '%':
            if digit:
                value = -0.34 if spaced else -0.2
            else:
                value = (-1.4 if spaced else -1.0) if lines else -0.75
        elif s.endswith('%'):
            value = -0.85
        elif s.endswith('@'):
            if previous.strip() == '*':
                value = -0.97
            else:
                value = -0.15 if spaced else -0.05
        elif '&#' in s:
            value = -1.95
        elif s.endswith('&'):
            value = -2.0 if attributes and closes > 2 else -0.1
        elif s in ('="', "='", 'class') and closes:
            density = len(ATTRIBUTE.findall(text))
            if closes > 2:
                value = -1.6 if density > 4 else -0.95
            else:
                value = -0.5
    joined = previous[-1:] + token
    lines += joined.count('\\n')
    hexes += joined.count('\\x') + joined.count('\\u')
    return (doc, (recent + token)[-1000:], token, lines, hexes), value

