"""Escape and markup detector for layer-0 MLP unit 152 (a negative-going feature).

It goes negative on the first token of an escape or markup sequence, and the more so when
the text around it is full of the same kind of syntax:
  - a literal escape (\\x, \\xe2, \\\\ or a bare backslash) in code or escaped text, with the
    strength growing with how many literal escapes ("\\n", "\\x..", "\\'") the last 40 tokens hold;
  - an opening HTML tag ' <' or '<', which grows with how many tags the last 40 tokens hold;
  - a closing tag '</', a tag join '><', a numeric/HTML entity '&#', a percent sign.
Ordinary words and punctuation give about zero.
"""
import re

READS = ()
WINDOW = 40
ESCAPE = re.compile(r"\\[nrtx\"'\\]")
TAG = re.compile(r"</?[a-zA-Z!]")

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids
    start = max(0, len(doc) - 1 - WINDOW)
    while start < len(doc) - 1 and doc[start] != doc[-1]:
        start += 1
    text = "".join(prefix.token_strings[start:-1])
    esc = min(len(ESCAPE.findall(text)), 4)
    tags = min(len(TAG.findall(text)), 4)
    if tok == "\\x":
        return None, -3.3
    if tok in ("\\xe", "\\xa", "\\xc"):
        return None, -2.1
    if tok in ("'<", " '<", '"><', "><", "&#", " &#"):
        return None, -2.0
    if tok in (" <", "<"):
        if prefix.token_strings[-2:-1] and prefix.token_strings[-2].endswith(">"):
            return None, -3.0
        return None, -0.2 - 0.45 * tags
    if tok in ("</", " </"):
        return None, -0.8
    if tok == "\\\\":
        return None, -1.0 - 0.1 * esc
    if tok == " \\":
        return None, -0.5 - 0.25 * esc
    if tok == "\\":
        return None, -0.2 - 0.15 * esc
    if tok in (" %", " {%"):
        return None, -1.2
    if tok in ("%", "'%"):
        return None, -0.2
