"""A spelling detector for passing/conveying, not general sentence meaning.

Training responses cluster around passing, transfer, copying, propagation, and file
upload/download words. The Chinese convey character 传/傳 and Japanese 伝
are especially strong. Compounds dilute this response, particularly tradition
and legend words. The detector also continues onto a following 'of' or split
word ending, resetting its one-token memory at each document boundary.
"""
READS = ()


def lexical(token):
    word = token.strip().lstrip('._/-(')
    chinese = word.replace('傳', '传')
    lower = word.lower()
    if chinese == '传':
        return -7.7
    if word == '伝':
        return -5.4
    if chinese == '上传':
        return -5.4
    if word in {'下载', '下載'}:
        return -1.35
    if chinese in {'流传', '传出', '传来'}:
        return -3.9
    if len(chinese) == 2 and '传' in chinese:
        if chinese in {'传统', '传統', '传奇'}:
            return -0.75
        if chinese in {'遗传', '遺传', '传真'}:
            return -1.1
        return -2.5
    if word == '伝え':
        return -2.4
    if word == 'truyền':
        return -3.4
    if word == '전':
        return -1.3 if token.startswith(' ') else -0.9
    if word == 'перед':
        return -0.7 if token.startswith(' ') else -0.25
    if lower == 'upload':
        return -3.5 if token.startswith(' ') else -4.1
    if lower in {'uploaded', 'uploading', 'uploads'}:
        return -2.9 if token.startswith(' ') else -2.2
    if lower in {'download', 'downloads', 'downloading'}:
        return -1.5 if word[0].isupper() else -1.3
    if lower == 'downloaded':
        return -1.0
    if lower == 'pass':
        if word != 'pass':
            return -0.82
        return -1.1 if token.startswith(' ') else -0.75
    if lower in {'passed', 'passing', 'passes', 'copy', 'copying', 'propag'}:
        return -1.15
    if lower in {'transfer', 'transmission', 'transmissions'}:
        return -1.25
    if lower in {'transferred', 'transferring', 'transfers',
                 'spread', 'spreads', 'spreading'}:
        return -1.0
    if lower in {'transmit', 'transmitted', 'transmitting', 'copies', 'copied',
                 'propagate', 'propagated', 'propagation', 'propaganda'}:
        return -0.8
    if lower in {'clone', 'clones', 'cloned', 'traditional', 'traditions',
                 'passage', 'passages', 'convey', 'conveyed', 'conveyor'}:
        return -0.4
    if lower in {'campaign', 'campaigns', 'teachings', 'preach'}:
        return -0.55
    if lower == 'tradition':
