    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else 0.0
    value = base = lexical(token)
    if token == ' of' and -2.0 < previous < -0.3:
        value = 0.65 * previous
    elif token in {'ed', 'ing', 'es'} and previous < -0.3:
        value = -0.4
    return (document, base), value

"""An opening-square-bracket detector with smaller ordinal and discourse
responses. Brackets fused to identifiers are strongest; empty brackets do
not count. Token boundaries and bracket quoting change the response.
Conversation/tool/thinking delimiters, carriage returns, ordinal endings,
English acknowledgments and several Chinese grammatical markers also respond.
Bare opening brackets are stronger early in a document and after whitespace.
"""
READS = ()

DELIMITERS = {
    '<|im_start|>': 0.45,
    '<|im_end|>': -0.14,
    '<tool_call>': 0.52,
    '<tool_response>': 0.34,
    '<think>': 0.58,
    '</think>': 0.39,
}
