CHINESE = {
    '但是': 0.44, '或者': 0.33, '以及': 0.60, '及': 0.21,
    '已经': 0.65, '已經': 0.53, '曾经': 0.40, '曾經': 0.40,
    '能够': 0.43, '能夠': 0.40, '可以': 0.14,
    '更加': 0.44, '按照': 0.47,
}
ORDINALS = {'th': 0.49, 'st': 0.20, 'nd': 0.25, 'rd': 0.24}


def bracket_response(token):
    text = token.lstrip(' ')
    if '[' not in text:
        return None
    before, after = text.split('[', 1)
    # A bracket closed within the same token is not an opening cue.
    if ']' in after:
        return 0.0
    spaced = token.startswith(' ')
    if not before:
        if '\n' in after:
            return 0.28 if spaced else 0.44
        if after[:1].isalpha() or after.startswith('_'):
            return 0.87
        if after.startswith(('"', "'")):
            return 0.64 if spaced else 0.55
        if after.startswith('@'):
            return 0.33 if spaced else 0.54
        if after.startswith('/'):
            return 0.37
        if after.startswith(':'):
            return 0.50
        return 0.56 if spaced else 0.78
    if before == '\\':
        return 0.52
    if before == '#':
        return 0.43
    if before.endswith(']'):
        return 0.12
    if before.endswith((')', '}')):
        return 0.50
    if before == '=':
        return 0.30
    if before == '(':
        return 0.25 if after else 0.14
    if before in ('"', "'", '`'):
        return 0.25
    return 0.10


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same = carry is not None and carry[0] == doc
    previous = carry[1] if same else ''
    position = carry[2] + 1 if same else 0
    token = prefix.token_strings[-1]
    text = token.strip()
    value = bracket_response(token)
    if value is not None:
        if token in ('[', ' ['):
            value = (0.49 if token.startswith(' ') else 0.76)
            value += 0.43 / (position + 1) ** 0.5
            if previous.isspace():
                value += 0.18
            if previous.endswith('\n'):
                value -= 0.08
            if previous.rstrip().endswith('\\'):
                value -= 0.25
    elif token in DELIMITERS:
        value = DELIMITERS[token]
        if token == '<|im_start|>' and position == 0:
            value = 0.17
    elif token == '\r':
        value = 0.86
    elif token in ORDINALS:
        value = ORDINALS[token] if previous[-1:].isdigit() else (
            0.12 if token == 'th' else 0.0)
    elif text.lower() == 'okay':
        value = 0.50
    elif text.lower() == 'alright':
        value = 0.36
    elif text.lower() == 'ok':
        value = 0.13
    elif text in ('eenth', 'teenth'):
        value = 0.29
    elif text.lower() in ('fifth', 'sixth', 'seventh', 'eighth', 'ninth'):
        value = 0.20
    elif text in ('【', '［'):
        value = 0.55
    else:
        value = CHINESE.get(text, 0.0)
    return (doc, token, position), float(value)

