"""Layer-0 MLP down-projection component 155: a "left square bracket" detector.

It is nearly silent on ordinary words, and fires on the opening square bracket "[" in
all its spellings (" [", "['", "[i", ...), which is where most of its variance lies.
It also fires weakly on a few structural chat/markup tokens (<|im_start|>, <tool_call>,
<think>, ...) and on the ordinal suffix "th" after a digit ("11th"). It is slightly
negative on the end-of-turn token <|im_end|>.

Predicted activation, per token:
  "[" at the start of a token ("[", "[i", "[x")  -> 0.75
  " [" or "['" / '["' (space or quote after bracket) -> 0.5
  any other token containing "["  (e.g. "][", "#[") -> 0.2
  <|im_start|>, <tool_call>, <tool_response>, <think>, </think> -> 0.4
  "th" right after a digit (ordinal suffix)       -> 0.5
  <|im_end|>                                       -> -0.12
  everything else                                  -> 0
"""

READS = ()

MARKUP = {"<|im_start|>", "<tool_call>", "<tool_response>", "<think>", "</think>"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if "[" in tok:
        if tok.startswith("["):
            value = 0.75
        elif tok.startswith(" [") or tok[:1] in "'\"":
            value = 0.5
        else:
            value = 0.2
    elif tok in MARKUP:
        value = 0.4
    elif tok == "th" and prev[-1:].isdigit():
        value = 0.5
    elif tok == "<|im_end|>":
        value = -0.12
    else:
        value = 0.0
    return carry, float(value)

