import unicodedata

READS = ()


def am_chunk(word, token, spaced, previous):
    before, after = word.split('am', 1)
    before = before.lstrip('._/@(')
    if word in ("'am", '-am'):
        return -2.7
    if not after:
        if not before:
            if token == 'Am':
                return -2.2 if spaced else -2.7
            if spaced:
                return -1.4 if previous.strip() == 'I' else -2.5
            return -4.0
        if len(before) == 1:
            return -3.25 if spaced else -3.9
        if word == 'param':  # Abbreviation for a software parameter.
            return -2.2
        if len(before) == 2:
            return -0.2 if before.endswith('e') else -2.1
        return -0.5 if len(before) == 3 else 0.0
    if after == 's' and len(before) <= 1:
        return -3.7 if not before and not token.isupper() else -2.7
    if not before:
        if after.startswith(('ent', 'on')):
            return 0.0
        if len(after) == 1:
            if after in 'lm':
                return -2.0
            return -1.6 if after == 'i' else -0.9
        return -0.75 if len(after) <= 3 else -0.1
    if len(before) <= 2 and len(after) == 1 and after != 'e':
        return -0.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.lower().replace('’', "'")
    spaced = raw[:1].isspace()
    value = 0.0
    if 'am' in word and word.isascii():
        value = am_chunk(word, token, spaced, previous)
    elif 'ам' in word:
        before, after = word.split('ам', 1)
        if not after and len(word) <= 4:
            value = -2.3 if spaced else -3.2
        elif not before and len(after) == 1:
            value = -0.9
    elif word == 'ям':
        value = -1.8
    elif 'ام' in word:
        before, after = word.split('ام', 1)
        if not after and len(before) <= 1:
            value = -2.5 if not before else -2.0
    elif word in ('람', '함'):  # Korean ram / ham syllables.
        value = -1.8
    elif len(word) == 2 and word[-1] == 'm':
        if unicodedata.normalize('NFD', word[0])[0] == 'a':
            value = -1.5
        elif word in ('pm', 'fm'):
            value = -1.0
    elif word in ('email', 'e-mail'):
        value = -0.8
    elif word == 'hmm':
        value = -0.4
    elif word == '拍':  # Chinese clapping / photographing character.
        value = -2.0
    elif len(word) <= 2 and '拍' in word:
        value = -1.1
    elif word == '啪':  # Chinese slap / pop sound.
        value = -0.8
    elif raw and set(raw) == {'\u00a0'} and 2 <= len(raw) <= 7:
        value = -0.65
    return (doc, raw), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:156 — an "am" spelling detector.

This component is almost silent everywhere. It goes strongly negative on the
current token when that token is spelled with the letters "am" (any case) as a
short syllable or word: "am", "AM", "ham", "lam", "ram", "Sam", "spam", "exam",
"iam", "param", "ams", and Cyrillic "ам" (вам, там, сам). The bare word " am"
(with a leading space) is weaker than "am" written without one. Words that
contain "am" but sound different ("example", "name", "camp", "program", "team",
"dream", "gram") stay near zero, and words ending in "-eam" (beam, seam, steam,
cream) are only mildly negative.

The program gives each token a predicted activation from its spelling alone:
no context, no state. It does not rebuild the model's computation.
"""

import re

READS = ()

# Spelling exceptions: words that end in "am" but do not respond.
NOT_AM = {"team", "teams", "dream", "dreams", "gram", "grams", "ogram", "ograms"}


def _letters(token):
    """The token's letters only, lower-cased (Latin and Cyrillic)."""
    return re.sub(r"[^a-zа-яё]", "", token.lower())


def _predict(token):
    word = _letters(token)
    leading_space = token[:1] == " "
    if word in ("am", "ам"):
        return -2.0 if leading_space else -4.0
    if word in ("param", "params"):
        return -2.3
    if word in NOT_AM:
        return 0.0
    if word.endswith("eam") and len(word) <= 5:
        return -1.0
    if word.endswith(("am", "ams", "ам")) and len(word) <= 5:
        return -2.5 if leading_space else -3.5
    return 0.0


def step(carry, prefix, upstream):
    return None, float(_predict(prefix.token_strings[-1]))

