    (0.63, {'id', 'fx:id'}),
    (0.52, {'style', 'align', 'colspan', 'for', 'rel'}),
    (0.47, {'src'}),
    (0.35, {'href', 'cref', 'type', 'lang', 'charset', 'placeholder',
            'width', 'height', 'size', 'target'}),
    (0.24, {'name', 'title', 'value', 'content', 'alt', 'border'}),
)
IMAGE_URL_PARTS = {
    '.unsplash': 0.62,
    '.imgur': 0.25,
    '.twitter': 0.45,
    '.blogspot': 0.55,
}
LAYOUT_CALLS = {
    '.createSequentialGroup': 1.20,
    '.setHorizontalGroup': 1.20,
    '.createParallelGroup': 0.58,
    'addComponent': 0.58,
    'addGap': 1.35,
    'addContainerGap': 1.35,
    'addGroup': 0.90,
    '.setBounds': 0.40,
}


