    elif joined.endswith('youtube.com/watch?v'):
        value = 0.80
    elif joined.endswith('shields.io/badge'):
        value = 0.70
    elif token == '-' and tail.endswith('unsplash.com/photo'):
        value = 0.66
    elif token == '&w' and 'unsplash.com/' in tail:
        value = 0.43
    elif token == 'Mouse' and tail.endswith('GetAxis("'):
        value = 0.80
    elif token == ' serialVersionUID' and tail.endswith('long'):
        value = 0.60
    elif token == ' from' and tail.endswith('without replacement'):
        value = 0.32
    if token.startswith('.') and token[1:] in TLDS:
        suffix, url = token[1:], bool(URL.search(tail))
        value = 0.25 if url else 0.10
        if suffix in {'org', 'edu'}:
            value = 0.03 if url else 0.0
        elif suffix == 'io':
            value = 0.43 if url else 0.20
        host = HOST.search(tail)
        if url and host and host[1] in {
            'imgur', 'unsplash', 'flickr', 'gstatic', 'shields'
