        elif token and not token.strip('#'):
            value = -0.20
        elif token in {'The', 'A', 'An', 'I', 'We', 'You', 'They',
                       'He', 'She', 'It', 'My', 'Your', 'Our'}:
            value = -0.10
        elif token in {'import', 'package', 'using', 'namespace'}:
            value = -0.10
    return (doc, joined[-512:], pos + 1), float(value)

