programs.sol:
"""Detect exposed a-umlaut fragments and replacement/comparison phrases.

ä/Ä is strongly negative in short letter pieces, less so when surrounded
by additional letters. The next piece of the same word gets a smaller,
length-dependent echo. æ, ă, ö and ü have weaker responses. 'instead of'
and 'rather than' are positive on the second word; quantity expressions
and ordinary comparisons get smaller positive values. All state resets
at document boundaries. This is a character/word-shape approximation.
"""
READS = ()
VOWELS = frozenset('aeiouäöü')
COMPARATIVES = frozenset(
    'less greater better lower smaller fewer higher other larger'.split()
)
QUANTITIES = frozenset(
    'couple plenty few most several majority half quarter'.split()
)


def letter_response(token):
    word = token.strip().lower()
    at = word.find('ä')
    if at >= 0:
        tail = word[at + 1:]
        if not tail:
            strength = 5.0
        elif tail == 'h':
            strength = 2.1
        elif tail in ('ß', 'z'):
            strength = 1.5
        elif tail == 'ä':
            strength = 3.4
        elif len(tail) == 1 and tail not in VOWELS:
            strength = 4.2
        elif len(tail) == 2 and not any(c in VOWELS for c in tail):
            strength = 1.4 if tail == 'lt' else 2.9
            if tail in ('mp', 'tz'):
                strength = 0.75
        else:
            strength = 1.4
        scale = 0.75 ** at * 0.87 ** max(0, len(tail) - 2)
        if at >= 2:
            scale *= 0.6
        if token[:1].isspace():
            scale *= 0.92
            if tail and len(word) <= 3:
                scale *= 0.5
        return -strength * scale
    for letter, strength in (('æ', 1.8), ('ă', 1.2),
                             ('ö', 0.34), ('ü', 0.29)):
        if letter in word:
            return -strength / (1 + 0.5 * max(0, len(word) - 1))
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0)
    _, previous, echo = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    base = letter_response(token)
    value = base
    if token.isalpha():  # No space: continuing a word.
        value += echo * (0.68 - 0.10 * min(len(token), 6))
    if word == 'of':
        value += 0.028
        if previous == 'instead':
            value += 1.58
        elif previous in QUANTITIES:
            value += 0.37
    elif word == 'than':
        if previous == 'rather':
            value += 2.48
        elif previous in COMPARATIVES:
            value += 0.42
    return (doc, word, base), float(value)

programs.luna:
"""Approximate activations from German letter patterns and a few English phrases."""

READS: tuple[str, ...] = ()
COMPARISON_WORDS = frozenset({
    "rather", "more", "less", "greater", "fewer", "other",
    "different", "better", "worse", "larger", "smaller",
})


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]

    old_document, ae_word, other_umlaut_word = carry or (document, False, False)
    has_space = any(character.isspace() for character in token)
    if document != old_document or has_space:
        ae_word = False
        other_umlaut_word = False

    has_ae = "ä" in token.lower()
    has_other_german_mark = any(mark in token for mark in "öüÖÜß")
    continues_ae_word = ae_word and not has_ae
    continues_other_umlaut_word = other_umlaut_word and not has_other_german_mark

    previous_word = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == document:
        previous_word = prefix.token_strings[-2].strip().lower()

    value = 0.001
    if has_ae:
        value -= 2.57
    if continues_ae_word:
        value -= 0.75
    if has_other_german_mark:
        value -= 0.12
    if continues_other_umlaut_word:
        value -= 0.06
    if token == " than":
        value += 0.10
        if previous_word in COMPARISON_WORDS:
            value += 0.22
        if previous_word == "rather":
            value += 2.19
    if token == " of":
        value += 0.03
    if token == " be":
        value -= 0.05

    if has_space:
        words = token.split()
        final_word = words[-1] if words and not token[-1].isspace() else ""
        ae_word = "ä" in final_word.lower()
        other_umlaut_word = any(mark in final_word for mark in "öüÖÜß")
    else:
        ae_word = ae_word or has_ae
        other_umlaut_word = other_umlaut_word or has_other_german_mark

    return (document, ae_word, other_umlaut_word), float(value)

