programs.sol:
"""Approximate the positive written-source and scholarly-citation response.

This is a vocabulary-and-notation detector, not a generic 'books' detector.
It recognizes scholarly source terms, old-text languages, publication places,
Roman volume numbers, citations, pronunciation signs and Chinese book characters.
Recent source cues boost ordinary book/edition words; their evidence fades
with distance and resets at each document. Other tokens are usually zero.
"""
READS = ()


def words(text):
    return frozenset(text.lower().split())


SOURCES = words('source sources press library libraries archive citation cited citing')
RECORDS = words('''
account accounts census tradition historian historians medieval poetry poet
poems prose corpus transcription translated documented dated
''')
TEXTS = words('''
manuscript manuscripts translation translations commentary scripture scriptures
bible biblical gospel gospels psalms genesis exodus matthew luke chronicles
''')
LANGUAGES = words('''
latin greek hebrew aramaic arabic chinese japanese korean persian armenian welsh
''')
CITIES = words('''
london paris york chicago moscow stockholm stuttgart cambridge oxford boston
edinburgh leipzig philadelphia
''')
FRAGMENTS = words('bib bibl bibli ibli ibr batim chrift criptions')
ROMAN = {'II', 'III', 'IV', 'VI', 'VII', 'VIII', 'IX', 'XI', 'XII',
         'XIII', 'XIV', 'XV', 'XVI', 'XX', 'XXX'}
BOOK_CHARS = set('本論記记志卷載载书書诗詩世紀曰')
AMBIGUOUS_BOOK_CHARS = set('注集經经')
BASE = {}
for value, group in (
    (0.25, SOURCES), (0.35, RECORDS), (0.50, TEXTS),
    (0.43, LANGUAGES), (0.37, CITIES), (0.35, FRAGMENTS),
    (0.18, words('write writes written wrote quote quotes spelled spelling')),
    (0.22, words('describe describes description origin origins')),
    (0.40, words('species genus described')),
    (0.70, words('century -century')),
    (0.45, words('centuries')),
    (0.60, words('bibliography quotations citations writings footnote reprint')),
):
    BASE.update(dict.fromkeys(group, value))
CUES = TEXTS | FRAGMENTS | words('''
verse verses bibliography citation citations cf ibid pp fol vol century
centuries -century latin greek hebrew ancient medieval
''')
ORDINARY_BOOK_WORDS = words('''
book books chapter chapters reference references edition editions
''')
CONTEXTUAL_TEXTS = TEXTS | CITIES
RECORD_LINKS = TEXTS | RECORDS | {'verse', 'volume'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, scholarly = 0, '', 0.0
    else:
        position, previous, scholarly = carry[1] + 1, carry[2], carry[3]
    token = prefix.token_strings[-1]
    word, spaced = token.strip(), token.startswith(' ')
    lower = word.lower()
    value = BASE.get(lower, 0.0)

    if lower in ORDINARY_BOOK_WORDS:
        value = 0.45 * scholarly
    if lower in {'text', 'volume', 'volumes'}:
        value = 0.13 + 0.60 * scholarly
    if lower in CONTEXTUAL_TEXTS:
        value += 0.40 * scholarly
    if spaced and lower in {'cf', 'ibid', 'supra', 'fol', 'vol', 'ff', 'pp'}:
        value = 0.50
        if lower == 'ibid':
            value = 1.0
        elif word == 'pp':
            value = 0.75
    if word in ROMAN or (spaced and lower in {'ii', 'iii'}):
        value = 0.50 if spaced or word in {'II', 'III', 'XX', 'XXX'} else 0.20
        if spaced and len(word) >= 3 and ('V' in word or 'X' in word):
            value = 0.75
    if spaced and lower in {'verse', 'verses'}:
        value = 0.80
    if not spaced and lower in {'ius', 'ica', 'orum', 'eus', 'iens', 'anus'}:
        value = 0.16  # Latin inflectional fragments.
    if lower in {'trad', 'trans', 'transl'}:
        value = 0.25  # Translation/bibliographic abbreviations.
    if not spaced and lower == 'ensis':
        value = 0.65  # Latin place-of-origin suffix.
    if word in BOOK_CHARS:
        value = 0.55 if word == '本' else 0.40
    if word in AMBIGUOUS_BOOK_CHARS:
        value = 0.10 + 0.60 * scholarly
    if word and all('\u1f00' <= ch <= '\u1fff' for ch in word):
        value = 0.30  # Polytonic Greek: older quoted texts.
    if word in {'ː', 'ˈ', 'ˌ'}:
        value = 0.30  # Pronunciation notation.
    if '§' in word:
        value = 0.35 if word == '§' else 0.50
    if token == ' p':
        value = 0.15 + 0.30 * scholarly
    if word == 'I':
        value = 0.18 * scholarly  # A pronoun unless the context suggests a volume.
    if word == 'See':
        value = 0.28
    if token == ' see':
        value = 0.25 if previous in {',', ';', ');', '.'} else 0.15 * scholarly
    if token == ' also':
        value = 0.48 if previous.lower() == 'see' else 0.12
        if previous in {',', ';', '.'}:
            value = 0.28
    if token == ' of' and previous.lower() in RECORD_LINKS:
        value = 0.25
    if word == '#' and position == 0:
        value = 0.83

    cue = lower in CUES or word in ROMAN or word in BOOK_CHARS
    scholarly = min(1.0, 0.985 * scholarly + 0.50 * cue)
    return (doc, position, word, scholarly), value

