programs.sol:
"""Approximate a response to encoded characters and tokenization boundaries.

Keep a 20-character tail, resetting at document boundaries. Recognize hex
byte escapes, Unicode escapes, percent escapes, escaped punctuation, and
HTML entities. Hex byte spellings receive the largest positive values;
ordinary text defaults to zero and common LaTeX operators to a small negative.
Also recognize Latin-1 mojibake and selected character classes when a token
finishes a split UTF-8 character: pronunciation marks, accented Latin letters,
control characters, and the integers symbol. These rules capture the sparse
encoding response, not the component's small word-specific fluctuations.
"""
import re
from html.entities import name2codepoint
import unicodedata

READS = ()
HEX = frozenset('0123456789abcdefABCDEF')
HTML_NAMES = frozenset(name2codepoint) | {'apos'}
MATH_OPERATORS = frozenset((
    'frac', 'sqrt', 'sum', 'int', 'partial', 'in', 'sim', 'approx',
    'le', 'ge', 'ne', 'to', 'over', 'left', 'big', 'begin',
))
MATH_FORMATTING = frozenset(('text', 'math', 'display', 'ref', 'prime'))


def escape_value(token, tail):
    byte = re.search(r'\\x([0-9a-fA-F]?)$', tail)
    if byte and token and token[0] in HEX:
        high = byte[1].lower()
        digit = token[0].lower()
        if not high:
            if len(token) == 2 and all(c in HEX for c in token):
                if token.isupper():
                    return 0.4
                if token == 'bb':
                    return 3.3  # Escaped closing guillemet.
                return 1.3 if tail[:-2].endswith('ef') else 2.3
            return 1.7 if digit == '9' else 1.55 if digit == '8' else 0.7
        if high == 'c':
            return 1.25
        if high == 'e':
            return 0.9
        if high == '8':
            return 0.0
        if high == '9':
            return 0.37 if digit in '89c' else 0.1
        if high == 'a':
            return 0.27 if digit == '6' else 0.6
        return 0.7

    if tail.endswith('\\'):
        if token.startswith('x') and len(token) > 1 and token[1] in HEX:
            return 2.1 if len(token) == 2 else 1.2
        if token in ('circ', 'limits'):
            return 1.3
        if token in MATH_OPERATORS:
            return -0.13
        if token in MATH_FORMATTING:
            return 0.1
        if token[:1] in ')]>,;*\"\'`_$|&#!^- ' and token:
            first = token[0]
            value = 0.85 if first in ')>' else 0.64 if first == ']' else 0.5
            if len(token) > 1:
                value *= 0.65
            if '\n' in token:
                value *= 0.7
            return value
        if token.startswith('['):
            return 0.22

    unicode_escape = re.search(r'\\u([0-9a-fA-F]{0,3})$', tail)
    if unicode_escape and token and token[0] in HEX:
        used = len(unicode_escape[1])
        if used == 0:
            return 0.75
        if used == 1:
            return -0.15
        if used == 2:
            return 1.3 if len(token) == 2 else 0.2
        return 0.25

    percent = re.search(r'%([0-9a-fA-F]?)$', tail)
    if percent and len(token) == 1 and token in HEX:
        if percent[1]:
            return 0.1
        return 0.6 if token in '2389' else 0.3 if token.isdigit() else 0.15

    entity = re.search(r'&(#?[A-Za-z0-9]*)$', tail)
    if entity:
        code = entity[1]
        if code == '#' and token[:1].isdigit():
            return 0.4
        if code.startswith('#') and token == '9':
            return 0.38
        name = code if token.startswith(';') else code + token
        if name in HTML_NAMES:
            quote = name.endswith('quo')
            umlaut = name.endswith('uml')
            if token.startswith(';'):
                value = 1.3 if umlaut else 1.15 if quote else 0.6
                return value if token == ';' else value * 0.5
            return 1.2 if umlaut else 0.9 if quote else 0.2
        if token.startswith(';') and code.startswith('#'):
            return 0.58 if token == ';' else 0.22
    return 0.0


def completed_character_value(char):
    """Character classes for a token that finishes a split UTF-8 character."""
    name = unicodedata.name(char, '')
    if name.startswith('HEBREW POINT'):
        if name.endswith('HOLAM'):
            return 2.1
        if name.endswith('TSERE'):
            return 1.6
        if 'DOT' in name:
            return 0.0
        if 'HATAF' in name:
            return 1.0
        if name.endswith(('QAMATS', 'PATAH', 'METEG')):
            return 0.35
        return 0.7
    if name.startswith('TIBETAN VOWEL SIGN'):
        return 2.25 if name.endswith(' U') else 1.3
    if name.startswith('SINHALA VOWEL SIGN'):
        return 1.5 if 'HAA' in name else 0.85
    if name.startswith('LATIN') and 'WITH' in name:
        base = unicodedata.normalize('NFD', char)[0].upper()
        if base in 'IOU':
            return 1.5 if base == 'U' else 0.9
        return 0.3
    if unicodedata.category(char) == 'Cc':
        return -0.25
    if char == 'ℤ':  # The mathematical symbol for the integers.
        return -0.85
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    tail = carry[1] if same_doc else ''
    token = prefix.token_strings[-1]
    value = escape_value(token, tail)

    # UTF-8 mistaken for Latin-1 produces familiar mojibake such as Ã©.
    # Repeated mis-decoding can also insert a control byte after the Ã.
    continuation = token.lstrip(' ')
    latin1_lead = re.search(r'([ÃÂ])(?:\x83 ?)?$', tail)
    if latin1_lead and continuation and 0x80 <= ord(continuation[0]) < 0xC0:
        value = 1.5 if latin1_lead[1] == 'Ã' else 0.5
        if continuation[0] in '»¼':
            value = 2.3
        if token.startswith(' ') and continuation[0] != '©':
            value = 0.3  # A space breaks the usual mis-decoded byte pair.
    if continuation == '¦' and 'â' in tail[-4:]:
        value = -1.0  # An ellipsis corrupted by a Latin-1/Windows-1252 decode.

    state_token = token
    if same_doc and '\ufffd' in token and prefix.token_strings[-2].endswith('\ufffd'):
        before = prefix.text_prefixes[-2]
        after = prefix.text_prefixes[-1]
        completed = after[len(before.rstrip('\ufffd')):]
        if completed and completed[0] != '\ufffd':
            value = completed_character_value(completed[0])
            tail = tail.rstrip('\ufffd')
            state_token = completed
            if completed[0] == '¦' and 'â' in tail[-4:]:
                value = -1.0
    return (doc, (tail + state_token)[-20:]), float(value)

"""A W-oriented spelling/lexical signal.

Initial W/w is stronger than an interior w; short letter fragments and
capitals are stronger still. Common words have calibrated exceptions,
notably weak "with" and "which". Related syllables in other scripts and
Chinese equivalents of several W words are also recognized. Split-word
continuations get a small bonus, reset at document boundaries. Two minor
responses are the two-hash marker, long whitespace tokens, and negative
"ve" contractions. Unmatched tokens receive zero.
"""

READS = ()

# Rounded training readings for common W words: grammatical and everyday words.
COMMON_W_WORDS = {
    'we': 1.32, 'was': 0.93, 'were': 0.91, 'will': 1.14,
    'would': 1.00, 'what': 0.64, 'when': 0.63, 'where': 0.88,
    'who': 0.71, 'whom': 1.0, 'whose': 1.0, 'why': 0.85,
    'while': 1.45, 'whether': 1.01, 'with': -0.08,
    'which': -0.08, 'without': 0.88, 'within': 0.70,
    'how': -0.30, 'however': 0.04, 'between': -0.08,
    'two': -0.07, 'down': -0.05, 'below': -0.13, 'otherwise': 0.04,
    'well': 1.49, 'always': 0.14, 'own': 0.99, 'now': 0.77,
    'away': 1.11, 'new': 0.51, 'way': 1.49, 'ways': 1.22,
    'want': 1.20, 'went': 0.68, 'wait': 1.80, 'few': 0.22,
    'water': 1.14, 'word': 1.51, 'words': 1.01,
    'website': 0.97, 'window': 1.31, 'woman': 1.33, 'women': 1.60,
    'werden': 0.97, 'wird': 1.03, 'whenever': 0.58,
    'wasn': 0.86, 'weren': 0.92, 'wouldn': 1.0,
}


# Frequent word families that are weak despite their written w.
SUPPRESSED_STEMS = {
    'allow', 'follow', 'show', 'know', 'answer', 'view', 'download',
    'low', 'lower', 'knowledge', 'review',
    'interview', 'overview', 'throw', 'unknown',
}


# Chinese equivalents of salient English W words.
CHINESE_W_WORDS = {
    '工作': 1.65, '工': 1.3, '水': 0.95, '世界': 1.7, '世': 1.4,
    '写': 1.55, '寫': 1.55, '白': 1.35, '走': 1.6, '走得': 1.4,
    '风': 1.1, '風': 1.1, '网': 1.05, '网站': 1.15, '网络': 0.9,
    '墙': 1.6, '牆': 1.6, '西': 0.95, '我们': 0.53, '将': 1.04, '將': 1.04,
}


def reading(s):
    word = s.strip().lstrip('._-/([{\'"`')
    low = word.lower()
    if low in COMMON_W_WORDS:
        return COMMON_W_WORDS[low] + (0.15 if word[:1].isupper() else 0.0)
    stem = low
    for suffix in ('ing', 'ed', 's', 'n'):
        if low.endswith(suffix) and len(low) > len(suffix):
            stem = low[:-len(suffix)]
            break
    if low in SUPPRESSED_STEMS or stem in SUPPRESSED_STEMS:
        return -0.05
    if stem == 'want':
        return 1.05
    if 'w' in low:
        i = low.index('w')
        if i == 0:
            if len(word) == 1:
                if word == 'W':
                    return 2.75
                return 1.85 if s[:1].isspace() else 2.5
            value = 1.8 + (0.45 if word[0] == 'W' else 0.0)
            if len(word) == 2:
                value += 0.7
            if not s[:1].isspace():
                value += 0.2
            if len(word) >= 8:
                value += 0.3
            return value
        value = 0.6
        if len(word) <= 3:
            value += 0.5
        if i == 1 and low[0] not in 'aeiou':
            value += 0.3
        if len(word) - i > 3:
            value += 0.15
        if len(word) > 7:
            value -= 0.15
        return value
    # Cyrillic ve and the Japanese/Thai spellings of wa.
    if word and word[:1] in 'вВ':
        return 0.7 if len(word) == 1 else 0.9
    if word.startswith(('ウォ', 'ウェ')):
        return 4.0
    if word in ('わ', 'ワ', 'ว'):
        return 2.6
    if word in ('ω', 'ώ', 'Ω'):
        return 0.9
    if word in CHINESE_W_WORDS:
        return CHINESE_W_WORDS[word]
    # Single Chinese syllables romanized with an initial w.
    if len(word) == 1 and word in '王旺文望万瓦慰玩伟吴温稳卧危维威晚围袜翁湾':
        return 1.6
    if len(word) == 1 and word in '为无完微问委味屋':
        return 0.65
    if s.strip() in ("'ve", '’ve'):
        return -0.65
    if s.strip() == '##':
        return 1.2
    if s and s.isspace():
        width = len(s.replace('\t', '').rstrip('\r\n'))
        width += 1 if '\t' in s else 0
        if 16 <= width <= 18:
            return 0.75 if '\t' not in s else 0.4
        if width >= 20:
            return 0.12
    return 0.0


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    token = prefix.token_strings[-1]
