    if (abs(value) < 0.2 and token.isascii() and token.isalpha()
            and previous[-1:].isalpha() and 'w' in previous.lower()):
        value += 0.75 if len(previous.strip()) <= 3 else 0.25
    return (doc, token), float(value)

