programs.sol:
"""Approximate the main positive triggers: 'some' tokens and semicolons.

This is a lexical detector, not a general quantity detector. A few
translations of 'some', plus 'many' and 'little', respond more weakly.
Recent code or mathematical/reasoning cues attenuate the main responses;
'how many' and 'a little' are weaker than the bare quantifiers.

Token boundaries matter: semicolons fused to brackets/quotes are weaker,
and a fused newline nearly removes the response. A semicolon completing
an HTML entity is not treated as prose punctuation. Unrecognized tokens
receive zero: this omits the component's many small lexical responses.
Main responses are also attenuated at the first token of a document.
The state is just the last 400 characters, reset at document boundaries.
"""
import re

READS = ()

# Translations of the indefinite quantifier 'some', including word stems.
SOME_TRANSLATIONS = {
    '一些': 0.59,
    '有些': 0.35,
    '些': 0.55,
    'некотор': 0.59,
    'einige': 0.32,
    'algunos': 0.44,
    'بعض': 0.45,
}


CODE = re.compile(
    r"```|\b(?:const|function|return|let|void|import|class|printf|std|def)\b"
    r"|==|=>|&&|\\n"
)
MATH = re.compile(
    r"[$=^]|\\(?:frac|sqrt|times)"
    r"|\b(?:equation|integer|theorem|triangle|Suppose|Maybe|think)\b"
)
ENTITY = re.compile(r"&(?:#\d+|[A-Za-z]{2,10})$")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else ''
    word = token.strip()
    value = 0.0
    sensitive = word.lower() in ('some', 'many', 'little') or word in (
        ';', '.;', ');', '];', '};'
    )
    code = bool(CODE.search(recent)) if sensitive else False
    math = bool(MATH.search(recent)) if sensitive else False
    if word.lower() == 'some':
        if token == 'Some':
            value = 1.36
        elif word == 'SOME':
            value = 0.91
        elif token == 'some':
            value = 1.11
        elif word == 'Some':
            value = 1.25
        else:
            value = 1.19
        value -= (0.14 if word == 'some' else 0.20) * code
        value -= (0.13 if word == 'some' else 0.18) * math
    elif word.lower() == 'many':
        value = 0.34 if word == 'Many' and token.startswith(' ') else 0.19
        value -= 0.30 * recent.lower().endswith('how') + 0.08 * math
    elif word.lower() == 'little':
        value = 0.36 if word == 'Little' else 0.24
        value -= 0.22 * recent.endswith(' a') + 0.07 * math
    elif word in SOME_TRANSLATIONS:
        value = SOME_TRANSLATIONS[word]
    elif word.endswith('一些'):
        value = 0.59
    elif word == '；':
        value = 0.41
    elif ';' in token and not any(c.isalnum() for c in token):
        if '\n' in token or '\r' in token:
            value = -0.035 if ')' in token else 0.0
        elif word in (';', '.;'):
            value = 0.46 - 0.09 * code - 0.13 * math
            if ENTITY.search(recent):
                value -= 0.42
            if recent and recent[-1].isdigit():
                value -= 0.03
        elif word in (');', '];', '};'):
            value = (0.44 if word == '};' else 0.34)
            value -= 0.06 * code + 0.13 * math
        elif word == ';\\':
            value = 0.19
        else:
            value = max(0.04, 0.40 - 0.14 * (len(word) - 1))
    if not recent and sensitive and token != 'Some':
        value *= 0.8
    return (doc, (recent + token)[-400:]), float(value)

programs.haiku:
"""Layer-0 MLP unit 167 is a "some" detector.

It fires on the English word "some" (and its capitalised form), on the
equivalent words in other languages (一些, некоторые, بعض, algumas, einige, ...),
more weakly on "many"/"little" and "some"-compounds (sometimes, somehow, ...),
and on a bare semicolon token (";", ";", "；", ".;", ");", "];").
Everything else is predicted as 0. Only the current token is read.
"""

SOME = {" some", " Some", "some", "Some", " SOME", "SOME"}
SOME_OTHER = {"ome": 0.44, "_some": 0.75, "一些": 0.6, "有些": 0.35, "某些": 0.25, " некотор": 0.6, " بعض": 0.45,
              " algumas": 0.35, " einige": 0.35, " 일부": 0.25, "不少": 0.25}
SOME_COMPOUNDS = {" somehow", " somewhere", " sometimes", " somewhat", " sometime", " someday"}
MANY_LITTLE = {" many": 0.15, " Many": 0.35, " little": 0.12}
SEMICOLONS = {";": 0.39, " ;": 0.38, "；": 0.41, ".;": 0.43, ");": 0.27, "];": 0.3}

READS = ()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in SOME:
        return None, 1.15
    if tok in SOME_OTHER:
        return None, SOME_OTHER[tok]
    if tok in SOME_COMPOUNDS:
        return None, 0.15
    if tok in MANY_LITTLE:
        return None, MANY_LITTLE[tok]
    if tok in SEMICOLONS:
        return None, SEMICOLONS[tok]
    return None, 0.0

