programs.haiku:
"""Candidate B: word classes for one MLP output direction in layer 0.

The component reads whole-word tokens. It leans positive on verbs (any inflection of a
common content verb), on clause-linking words and adverbs, and on modals; it leans
negative on pronouns, suffix fragments and function words; everything else is near zero.
"""
READS = ()

BASE_VERBS = """use show present set test return work check know look cause print study match note
notice end exit include need help let learn keep add follow pass require offer combine
write run build call create change provide allow start try remain seem become mean reduce
increase define support apply consider open close move hold turn play read send pick ask
talk think tell feel leave put bring happen sit stand lose pay meet continue lead understand
watch stop speak spend grow win teach begin believe carry draw break choose cut eat fall
fill hit join kill land list mark miss pull push reach realize receive reply rise rule save
serve sell shut sign sing sleep spread stick strike suggest throw touch treat wear""".split()


def _forms(base):
    """The base form and its -s, -ed, -ing forms (roughly)."""
    forms = {base, base + "s", base + "ed", base + "ing"}
    if base.endswith("e"):
        forms |= {base + "d", base[:-1] + "ing"}
    if base.endswith("y"):
        forms |= {base[:-1] + "ies", base[:-1] + "ied"}
    return forms


VERBS = set().union(*(_forms(b) for b in BASE_VERBS))
LINKING = set("""if because while so either though although since unless once now even only just
back out down up right about after under within over outside again also still then""".split())
MODALS = set("can will must need needs should would could may might shall".split())
FUNCTION = set("of to in on at for with from by into through as the a an this that".split())
PRONOUNS = set("it he she they we you i me him her them us his its their our your my".split())


def _is_cjk(word):
    return any("一" <= ch <= "鿿" for ch in word)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    spaced = token.startswith(" ")
    if _is_cjk(word):
        value = 0.04
    elif not word:
        value = 0.0
    elif not spaced and word in ("ing", "ed", "ly", "s"):
        value = -0.04
    elif spaced and word in VERBS:
        value = 0.18
    elif spaced and word in LINKING:
        value = 0.17
    elif spaced and word in MODALS:
        value = 0.07
    elif word in FUNCTION:
        value = -0.01
    elif word in PRONOUNS:
        value = -0.01
    else:
        value = 0.0
    return carry, float(value)

