programs.sol:
"""Abbreviation-ending dots, with a weak short-word fallback.

Recognize common titles, reference abbreviations, dates, places, and dotted
initialisms. Predict negative pulses on their final dots, adjusting for
punctuation merged into the same token. A separate following space retains
part of the pulse. Short lowercase word fragments have a weaker response.
Section signs and space-prefixed dots get small negative responses.
Fine token-specific and long-context variations are deliberately omitted.
"""
import re

READS = ()

# Familiar abbreviation families share an approximate activation magnitude.
FAMILIES = (
    # Titles and Latin shorthand.
    (3.3, 'Mr Mrs Ms Prof prof Rev Hon Sr Jr Gen Rep Sen Fr al cf sp spp resp Resp rel'),
    (4.1, 'Dr Lt Gov Inc INC Corp Bros'),
    # Figures, references, and geographic abbreviations.
    (3.1, 'Fig fig No Vol vol pp Sec Sect Ch Nr Acc Eqn Rec Dep Pres Pub'),
    (4.5, 'FIG Eq eq Eqs Ref Cir Dist Nos St Mt'),
    (2.6, 'Pat Col Fed Vet Res Doc Hist Ct Univ Inst Soc Proc Supp '
     'Co Ltd Ave Rd Blvd Ft ft Rs Phys Chem'),
    # Dates and place names.
    (4.2, 'Jan Feb Mar Apr Jun Jul Aug Sep Sept Oct Nov Dec'),
    (2.6, 'Calif Cal Conn Fla Ill Ind Ky Mass Md Mich Minn Mo Mont Nev '
     'Ore Pa Tenn Tex Va Vt Wash Wis'),
    # Grammatical shorthand, units, and non-English abbreviations.
    (2.1, 'App adj adv Intr tr'),
    (2.7, 'Figs FIGS figs'),
    (2.5, 'sec hr wt lb oz sq fl approx ca'),
    (4.1, 'bzw vgl Vgl'),
    (2.5, 'vergl desgl Mitgl inkl'),
    # Short reference forms and discourse words.
    (1.8, 'etc no Hmm hmm Art Id op ib'),
    (1.5, 'p Pp'),
    (5.0, 'vs Vs'),
    (2.5, 'v'),
    (3.1, 'г т'),
    (4.5, 'тыс'),
    (1.0, 'c'),
)
FORMS = {w: n for n, words in FAMILIES for w in words.split()}
WORD = re.compile(r'([^\W\d_]+(?:\.[^\W\d_]+)*)$')
LATIN = {'e.g', 'i.e', 'p.m', 'a.m', 'p.p.m', 'c.f'}
DOMAINS = {'com', 'org', 'net', 'edu', 'gov', 'io', 'py', 'js', 'css'}


def pulse(word):
    if word in FORMS:
        return FORMS[word]
    if word.isupper() and word.title() in FORMS:
        return 0.45 * FORMS[word.title()]
    if word.lower() in LATIN:
        return 3.9
    if word in {'S.Ct', 'Pl.Ex'}:
        return 5.0
    if word in {'F.Supp', 'Cal.Rptr'}:
        return 3.3
    if '.' in word and word.isascii():
        parts = word.split('.')
        if parts[-1] in {'sub', 'sup'}:
            return 3.0
        if all(len(p) <= 3 for p in parts) and parts[-1] not in DOMAINS:
            return 2.9
        return 0.8 * FORMS.get(parts[-1], 0.0)
    if len(word) == 1 and word.isascii():
        return 0.55 if word.islower() else 0.0
    if word.istitle() and len(word) <= 4:
        return 0.8 if len(word) <= 3 else 0.35
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, last, previous = '', 0.0, ''
    else:
        _, tail, last, previous = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token.strip() in {'§', '§§'}:
        value = -0.65
    elif token == ' .':
        value = -0.3
    elif token == ' ' and previous == '.':
        value = -0.2 + 0.38 * min(last, 0.0)
    elif token.startswith('.') and not token.startswith('..'):
        suffix = token[1:]
        if not any(c.isalnum() for c in suffix):
            match = WORD.search(tail)
            strength = pulse(match.group(1)) if match else 0.0
            if not strength and previous.isalpha() and previous.islower():
                strength = {1: 0.45, 2: 0.25, 3: 0.12}.get(len(previous), 0.0)
            if not suffix:
                value = -0.01 - strength
            elif '\n' in suffix or '\r' in suffix:
                value = 0.03 - 0.25 * strength
            elif suffix[0] in ',;:':
                value = -1.25 - 0.33 * strength
            elif ')' in suffix:
                value = -0.7 - 0.65 * strength
            elif any(c in suffix for c in '-–—'):
                value = -0.6 - 0.5 * strength
            else:
                value = -0.02 - 0.4 * strength
    tail = (tail + token)[-96:]
    tail = tail.replace('\\n', ' ').replace('\\r', ' ').replace('\\t', ' ')
    return (doc, tail, value, token), float(value)

programs.haiku:
"""Layer-0 MLP down-projection unit 169: a detector for a period that ends an abbreviation.

The unit is strongly negative on the period that closes an abbreviation: titles and
abbreviations such as Dr. Mr. St. Fig. No. vs. Inc. Aug. pp. Sect. Proc. ft., initials and
acronyms (U.S., a.m., e.g., i.e.), and short unfamiliar capitalised words that take a
period. Ordinary sentence-ending periods, ellipses, periods before a newline, and commas
after ordinary words stay near zero. The bare space that follows such a period (as in
"FIG. 1") carries about half the signal. The program is a rule over the token strings.
"""

READS = ()

# Abbreviations that reliably take a period: titles, figure/page/volume words, units,
# months, company and Latin forms, and web prefixes.
ABBREVIATIONS = {
    "mr", "mrs", "ms", "dr", "prof", "st", "ave", "fig", "figs", "no", "nos", "eq", "eqs",
    "vs", "vol", "vols", "art", "sec", "sect", "inc", "co", "corp", "ltd", "jr", "sr", "gen",
    "capt", "col", "gov", "pres", "rev", "univ", "dept", "dist", "inst", "cir", "ct", "aug",
    "oct", "nov", "dec", "jan", "feb", "mar", "apr", "jun", "jul", "sep", "sept", "pat",
    "ref", "cf", "bros", "assoc", "calif", "mich", "conn", "colo", "ill", "wash", "tex",
    "pp", "proc", "comm", "stat", "resp", "rel", "ext", "spp", "sp", "ft", "oz", "lb", "lbs",
    "wt", "cub", "cu", "pt", "pl", "eds", "ed", "trans", "suppl", "rptr", "www", "vgl", "gl",
    "fl", "rec", "hist", "qs", "igs", "déc",
}
# Weaker: abbreviations that often end sentences or are ambiguous.
WEAK = {"etc", "al", "ca", "ed", "approx", "eg", "ie", "sub", "app", "adv", "hon", "sup", "min", "hr", "hrs"}


def closing_strength(tokens, i):
    """How strongly the period-like token at index i closes an abbreviation (0 if not)."""
    core = tokens[i].lstrip(" ")
    if not core.startswith(".") or ".." in core or set(core) - set(".,;:)(\"'"):
        return 0.0  # only a bare period, optionally followed by , ; : ) ( " '
    if i == 0:
        return 0.0
    word = tokens[i - 1].strip()
    if word.startswith(".") and word[1:].isalpha():
        return -2.8  # a letter after a period, as in U.S. or a.m.
    word = word.strip(".")
    if not word.isalpha():
        return 0.0
    if word.lower() in ABBREVIATIONS:
        return -3.5
    if word.lower() in WEAK:
        return -1.5
    if word[0].isupper() and word[1:].islower() and len(word) <= 3:
        return -2.2  # unfamiliar capitalised short word: Dr-like
    if word.isupper() and len(word) <= 3:
        return -1.0
    if len(word) == 1:
        return -0.7  # lone letter, as in e.g. or p. c. v.
    return 0.0


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    i = len(tokens) - 1
    if tokens[i] in (" ", "\xa0") and i > 0:
        # the bare space after an abbreviation's period carries about half of it
        return carry, 0.5 * closing_strength(tokens, i - 1)
    return carry, closing_strength(tokens, i)

programs.sol:
"""Approximate the component's contrast at an a-like token boundary.

A short a-ending gates a score for the next letter or syllable: Latin
vowel clusters and Japanese vowel lengthening are negative, while many
consonant onsets are positive. Sonorants and long pieces are weaker.
Script-specific rules extend this spelling pattern beyond Latin letters;
they are not a general phonetic transcription. Spaces normally suppress
it, except for familiar English constructions such as 'a bit' and
'a number of'. Byte fragments are repaired only when needed, and state
resets at document boundaries. Fine lexical/contextual variation is omitted.
"""
import unicodedata as ud
from functools import lru_cache

READS = ()
VOWELS = {'a': -1.3, 'e': -0.8, 'i': -0.3, 'o': -1.6, 'u': -2.0}
SONORANTS = {'l': 0.0, 'r': 0.1, 'm': 0.35, 'n': 0.2,
             'w': 0.25, 'y': 0.25}
A_PHRASES = {'number': -2.2, 'more': -1.37, 'given': -1.3,
             'bit': 0.64, 'little': 0.35, 'name': -1.2,
             'further': -0.53, 'very': -0.4, 'one': -0.64,
             'single': -0.24, 'small': -0.34, 'wide': -0.39,
             'second': -0.27, 'third': -0.49, 'less': -0.48}
A_KANA = frozenset(
    'ぁあかがさざただなはばぱまゃやらゎわ'
    'ァアカガサザタダナハバパマャヤラヮワ'
)
A_PINYIN = frozenset('阿巴帕马馬麻拉娜纳納卡咖哈沙莎萨薩塔瓦')

@lru_cache(maxsize=8192)
def plain(s):
    return ''.join(c for c in ud.normalize('NFKD', s.lower())
                   if not ud.combining(c))

@lru_cache(maxsize=8192)
def a_ending(s):
    if not s:
        return 0.0
    c = s[-1]
    if '가' <= c <= '힣':
        syllable = ord(c) - 0xAC00
        if syllable % 28:
            return 0.0  # a final consonant closes the syllable
        # Unicode vowel indices: a=0, ya=2, eo=4, yeo=6, wa=9.
        vowel = syllable // 28 % 21
        return {0: 1.0, 2: 1.0, 4: 0.25, 6: 1.0, 9: 0.3}.get(vowel, 0.0)
    p = plain(s)
    if c.lower() == 'ä':
        return 0.45
    if c in A_KANA and 'ぁ' <= c <= 'ゖ':
        return 0.1
    if (not p or p[-1] not in 'aαаяا') and c not in A_KANA | A_PINYIN:
        return 0.0
    length = len(s.strip())
    if length <= 2:
        return 1.0
    return {3: 0.8, 4: 0.5}.get(length, 0.15)

@lru_cache(maxsize=8192)
def onset(s):
    """A vowel/consonant contrast, with weak responses to sonorants."""
    if not s:
        return 0.0
    c = s[0]
    if c == 'ー':
        return -3.3 if '�' in s else -1.8  # Japanese vowel lengthening
    if '가' <= c <= '힣':
        syllable = ord(c) - 0xAC00
        initial = syllable // 588
        if initial == 11:
            return 1.3 if syllable // 28 % 21 in (0, 2) else -0.2
        # Hangul onset order: g,gg,n,d,dd,r,m,b,bb,s,ss,ng,j,jj,ch,k,t,p,h.
        return (1.0, 1.2, 0.2, 1.0, 1.2, 0.1, 0.35, 1.0, 1.2,
                1.2, 1.4, -0.6, 1.3, 1.4, 1.4, 1.2, 1.2, 1.1, 1.0)[initial]
    p = plain(s)
    if not p:
        return 0.0
    c = p[0]
    if c in VOWELS:
        if len(p) == 1:
            return {'a': -0.4, 'e': -0.15, 'i': 0.0,
                    'o': -0.65, 'u': -0.75}[c]
        value = VOWELS[c]
        # The em/en/um/un continuations have a stronger negative response.
        if c in 'eu' and p[1] in 'mn':
            value -= 0.7
        return value
    if c in SONORANTS:
        return SONORANTS[c]
    if c in 'bcdfghjkpqstvxz':
        return 1.7 if c == 'z' else 1.5 if c in 'cd' else 1.2
    if c in 'αεηιουω':
        return -0.1
    if c in 'βγδζθκλμνξπρστφχψς':
        if c == 'τ':
            return 2.55
        if c in 'δζκχ':
            return 1.85
        if c == 'σ':
            return 1.8
        return {'λ': 0.4, 'μ': 0.85, 'ν': 0.35, 'ρ': 0.55,
                'ξ': 0.65, 'ς': 0.5}.get(c, 1.2)
    if c in 'аоу':
        return -1.0 if len(s) == 1 else -1.5
    if c in 'еёиыэя':
        return 0.0
    if c == 'ю':
        return 0.5 if len(s) == 1 else 0.1
    if 'б' <= c <= 'щ':
        return {'л': 0.0, 'р': -0.3, 'м': 0.5, 'н': 0.3,
                'в': 0.4, 'х': 0.8}.get(c, 1.65 if c in 'жзцчшщ' else 1.4)
    name = ud.name(s[0], '')
    if name.startswith(('HIRAGANA LETTER ', 'KATAKANA LETTER ')):
        syllable = name.split()[-1].lower()
        return VOWELS.get(syllable[0], SONORANTS.get(syllable[0], 1.2))
    if '\u0600' <= c <= '\u06ff':
        if c in 'ويی':
            return -1.4 if c == 'و' else -0.2
        if c in 'لمنر':
            return {'ل': -0.2, 'م': 0.2, 'ن': 0.0, 'ر': -0.1}[c]
        return 1.2 if c in 'كکجچزخغ' else 0.55 if c in 'دطضفشس' else 0.25
    return 0.0


def boundary_response(previous, token, before):
    strength = a_ending(previous)
    if not strength:
        return 0.0
    if token[:1].isspace():
        if plain(previous.strip()) != 'a':
            return 0.0
        word = plain(token.strip())
        if len(token.strip()) == 1:
            return 0.6 * strength * onset(token.strip())
        if word == 'name' and '<' in before:
            return -3.2  # an HTML anchor's name attribute
        return A_PHRASES.get(word, 0.0)

    body = token
    if token.startswith('-') and previous.endswith('A'):
        body = token[1:]  # alphabet ranges such as a-zA-Z
    length = len(body)
    vowel = bool(body) and plain(body)[:1] in 'aeiou'
    if vowel:
        scale = 1.0 if length <= 4 else 0.65
    else:
        scale = 1.0 if length <= 2 else 0.65 if length <= 4 else 0.2
    return strength * scale * onset(body)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before, last_value = '', '', 0.0
    else:
        _, previous, before, last_value = carry

    raw = prefix.token_strings[-1]
    token = raw
    if '�' in raw:
        end = prefix.text_prefixes[-1][-1:]
        if end and end != '�':
            token = (' ' if raw[:1].isspace() else '') + end

    if (raw.startswith('�') and previous.startswith('ー')
            and last_value < -0.5):
        value = 0.27 * last_value  # finish a split vowel-lengthening piece
    elif (plain(token.strip()) == 'of'
            and plain(previous.strip()) == 'number'):
        value = min(last_value, 0.0) * 0.8
    else:
        value = boundary_response(previous, token, before)
    return (doc, token, previous, float(value)), float(value)

"""Approximate a short-fragment Z feature, not a phonetic transcription.

Short initial z/з spellings give the main positive response, strengthened by
capitals and weakened within an already-started word. Internal z and related
z/j/zh spellings in other scripts have smaller responses. A fragment after
final z/з gets an echo, or suppression if it also contains z. Separate cues
are weekdays/week, JSON, free, central/chapter, ounces, a cross sign and the
tool-response terminator. <think> is mildly negative; zero and Arabic
demonstratives are attenuated. Document changes reset the previous fragment.
The rules omit individual tokens' idiosyncratic strengths.
"""
READS = ()
DAYS = {'monday', 'tuesday', 'wednesday', 'thursday', 'friday',
        'saturday', 'sunday', 'yesterday', 'week', 'weekly'}
# Common characters with a Mandarin z- or zh-initial reading.
CHINESE_Z = set(
    '子自字资紫姿仔籽滋兹扎杂咱赞暂早造遭糟澡灶走奏'
    '泽责择贼怎曾增赠纵宗综尊遵祖租阻组足族卒坐做醉罪嘴宰'
)
CHINESE_ZH = set(
    '张張章帐障彰涨掌丈仗胀账杖漳知只之支枝汁织质制治'
    '致至志智址指纸止趾值执直置职侄秩中种種重众钟忠仲'
    '终肿衷周週州洲舟粥轴皱宙咒昼逐住注柱助祝珠猪朱竹'
    '筑著驻駐铸株嘱真正照招郑赵'
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = '' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    # A byte-fragment token can complete a character from the preceding token.
    if raw == '\ufffd' and prefix.text_prefixes[-1][-1:] != '\ufffd':
        raw = prefix.text_prefixes[-1][-1:]
    word = raw.strip().lower()
    letters = ''.join(c for c in word if c.isalpha())
    n = max(1, len(letters))
    upper = next((c.isupper() for c in raw if c.isalpha()), False)
    connected = raw.isalpha() and prev[-1:].isalnum()
    latin = letters.replace('з', 'z')
    value = 0.0
    if 'z' in latin:
        if latin.startswith('z'):
            value = 2.7 - 0.5 * (n == 1) - 0.3 * max(n - 3, 0)
            value += 0.9 * upper - 0.7 * connected
            value -= 0.15 * raw[:1].isspace()
            value += 0.25 * (word[:1] and not word[0].isalpha())
            value -= 0.25 * latin.startswith('ze')
            value += 0.8 * (latin in {'zh', 'zw'})
            if 'з' in letters:
                value += (0.45 if n == 1 else -0.05) - 0.6 * upper
        else:
            value = 1.1 - 0.1 * n + 0.2 * upper
            if not upper and any(d in latin for d in ('cz', 'sz', 'rz')):
                value *= 0.1
        value = max(0.0, value + 0.5 * ('zz' in latin))
    if any(c in letters for c in 'žźżж'):
        value += max(0.0, 1.0 - 0.13 * n)
    if any(c in letters for c in 'زذ'):
        value += max(0.0, 2.0 + 1.3 * raw[:1].isspace() - 0.5 * (n - 1))
    if any(c in letters for c in 'ضظ'):
        value += 1.4 / n
    # Greek zeta, Hebrew zayin, Georgian zen, Armenian za.
    if any(c in letters for c in 'ζזზզ'):
        value += 1.1 + upper
    if any(c in raw for c in 'ざずぜぞザズゼゾ'):
        value += (2.0 + 1.4 * any(c in raw for c in 'ざザ')) / n**1.5
    elif any(c in raw for c in 'じジ'):
        value += 0.8 / n**2
    # Hangul: 588 syllables per initial; indices 12/13 are j/tense j.
    if any(0xAC00 <= ord(c) <= 0xD7A3 and
           (ord(c) - 0xAC00) // 588 in (12, 13) for c in raw):
        value += 0.85 / n**2
    if any(c in CHINESE_Z for c in raw):
        value += 0.6 / n
    elif any(c in CHINESE_ZH for c in raw):
        value += 0.85 / n
    if prev.lower().endswith(('z', 'з')) and raw.isalpha():
        value += -0.4 if 'z' in latin else 0.55
    if word in DAYS:
        value += 0.6
    if 'json' in word:
        value += 0.55
    if word in {'free', '-free', '_free'}:
        value += 0.65
    if word == 'central' or word in {'chapter', 'chapters'}:
        value += 0.7
    if word in {'ounce', 'ounces', '</tool_response>'}:
        value += 1.0
    if word == 'zero':
        value = max(0.0, value - 0.4)
    if word == '<think>':
        value -= 0.35
    if '✝' in raw:
        value += 1.4
    if word in {'هذا', 'هذه', 'ذلك', 'تلك'}:
        value = 0.0
    return (doc, raw), float(value)

"""A local English construction detector, dominated by possibility + 'be'.

Look back up to five token pieces for a modal, allowing pronouns/adverbs
and joining split negations. 'Can/could/cannot be' gets a large negative
value; other modals, selected verb--'to' constructions, and mental-state
clauses get weaker signed values. These rules approximate the prominent
training patterns, not the component's many small lexical responses.
History resets at document boundaries; unrecognized tokens predict zero.
"""
READS = ()

MODALS = {
    'can': -1.07, 'could': -0.99, 'cannot': -1.31,
    'may': -0.26, 'might': -0.22, 'must': -0.24,
    'should': -0.15, 'would': 0.03, 'will': 0.11, 'shall': 0.03,
}
SUBJECTS = {'it', 'this', 'that', 'they', 'we', 'you', 'he', 'she', 'there'}
ADVERBS = {
    'also', 'only', 'not', 'never', 'always', 'still', 'then', 'now',
    'ever', 'even', 'both', 'all', 'very', 'well', 'instead', 'just', 'best',
    'sometimes', 'likewise', 'indeed', 'therefore', 'already',
}
ARRIVAL = {'come', 'comes', 'came', 'coming', 'get', 'gets', 'got', 'getting'}
EVENTS = {'happen', 'happens', 'happened', 'happening', 'occur', 'occurs', 'occurred'}
CHOICE = {'decide', 'decides', 'decided', 'deciding'}
FAILURE = {'fail', 'fails', 'failed', 'failing', 'forget', 'forgot', 'forgotten'}
MENTAL_STATES = {
    'think', 'thinks', 'thought', 'know', 'knows', 'knew', 'suppose', 'sure',
}
RETURN = {'return', 'returns', 'returned', 'returning'}
REFERENCE = {'refer', 'refers', 'referred', 'referring', 'respect', 'regard'}

TO_CONTEXTS = (
    (ARRIVAL, -0.60),
    (EVENTS, -0.73),
    (CHOICE, 0.52),
    (RETURN | REFERENCE, -0.32),
    ({'listen', 'listens', 'listened', 'listening', 'attention'}, -0.56),
    (FAILURE, -0.37),
    ({'sure'}, 0.39),
    ({'able'}, 0.20),
    ({'used'}, -0.24),
)
OTHER_MODAL_VERBS = {'see': 0.24, 'help': 0.25, 'do': 0.12, 'have': 0.22}


def modal_value(words):
    modifiers = []
    for word in reversed(words):
        negative = word.endswith(("n't", 'n’t'))
        base = word[:-3] if negative else word
        base = {'ca': 'can', 'wo': 'will', 'sha': 'shall'}.get(base, base)
        if base in MODALS:
            value = MODALS[base]
            if negative:
                value -= 0.28 if base in {'can', 'could'} else 0.22
            if 'not' in modifiers:
                value -= 0.18
            if 'never' in modifiers:
                value -= 0.30
            if 'also' in modifiers:
                value -= 0.11
            if 'then' in modifiers:
                value += 0.15
            if 'very' in modifiers and 'well' in modifiers:
                value += 0.28
            return value
        if word in ADVERBS or word in SUBJECTS or word.endswith('ly'):
            modifiers.append(word)
        else:
            break
    return -0.08


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    words = () if carry is None or carry[0] != doc else carry[1]
    word = prefix.token_strings[-1].strip().lower()
    previous = words[-1] if words else ''
    value = 0.0
    if word == 'be':
        value = modal_value(words)
    elif word == 'to':
        value = -0.015
        for category, response in TO_CONTEXTS:
            if previous in category:
                value = response
                break
    elif word == 'that' and previous in MENTAL_STATES:
        value = 0.34
    elif word in OTHER_MODAL_VERBS:
        modal = modal_value(words)
        if modal < -0.50:
            value = modal * OTHER_MODAL_VERBS[word]
            if word == 'help' and modal < -1.15:
                value = -0.50
    if word in {"'t", '’t', "n't", 'n’t'} and words:
        words = words[:-1] + (previous + word,)
    else:
        words = words + (word,)
    return (doc, words[-5:]), value

programs.haiku:
"""layers.0.mlp.down_proj:172: a "be after a modal" detector, plus two small side effects.

What it does, in plain terms. This component is quiet almost everywhere. Its main job is to go
strongly negative on the word "be" when a modal of possibility comes before it: "it can be
seen", "cannot be used", "could be". "May", "must", "might" and "should" give a weaker
negative; "will", "would" and "shall" give none. Adverbs between the modal and "be" ("can
also be", "can only be") weaken it. Two smaller effects follow the same idea:
- "to" that starts an infinitive after a verb of intent or ability ("decided to", "able to",
  "sure to") is mildly positive, while "to" in a fixed prepositional or idiomatic phrase
  ("come to", "get to", "happen to", "attention to", "used to") is mildly negative.
- The complementizer "that" or "it" after a verb of thinking or knowing ("I think that",
  "I know it") is mildly positive.
Everything else predicts 0.

Main program: `step` looks only at the current token and the few tokens before it, within the
same document, and returns the value from the tables below.
"""

READS = ()

# How strongly "be" is pushed negative by the modal before it.
MODAL_BE = {
    "cannot": -1.3, "can": -1.1, "could": -1.0, "may": -0.26,
    "must": -0.24, "might": -0.22, "should": -0.15, "will": 0.1, "would": 0.03, "shall": 0.03,
}
# Adverbs that can sit between a modal and "be"; they keep part of the modal's effect.
ADVERBS = {"also", "only", "not", "never", "always", "still", "even", "easily", "well", "just"}
TO_INFINITIVE = {
    "decide", "decided", "decides", "decision", "choose", "chose", "chosen", "able", "sure",
    "designed", "determined", "limited", "impossible", "likely", "possible", "easy",
    "difficult", "time", "thought", "aim", "aims", "intended", "sufficient", "solution",
}
TO_IDIOM = {
    "come", "came", "comes", "happen", "happened", "happens", "get", "gets", "got",
    "attention", "listen", "listening", "regard", "regards", "respect", "return", "returned",
    "returning", "returns", "used", "meant", "failed", "fail", "fails", "refer", "refers",
    "referring", "referred", "relate", "relates", "related", "relating", "belong", "belongs",
    "seem", "seems", "seemed", "appears", "forget", "reported", "subscribe",
}
THINK = {"think", "thinks", "thought", "know", "knows", "knew", "suppose", "sure", "find"}


def _word(token):
    return token.strip().lower()


def _be_value(words):
    """Activation on a "be" whose preceding words (newest last) are `words`."""
    i = len(words) - 1
    weight = 1.0
    while i >= 0 and words[i] in ADVERBS | {"'t", "’t"}:
        if words[i] in ADVERBS:
            weight *= 0.6
        i -= 1
    if i < 0:
        return -0.1 * weight
    if words[i] in MODAL_BE:
        return MODAL_BE[words[i]] * weight
    return -0.1 * weight  # "to be", "will be" etc. carry only a little


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    docs = prefix.document_ids
    t = prefix.position
    # Only look back within the current document: attention resets at a document change.
    start = max(0, t - 4)
    while start < t and docs[start] != docs[t]:
        start += 1
    words = [_word(tokens[i]) for i in range(start, t)]
    cur = tokens[t].strip()
    prev = words[-1] if words else ""
    value = 0.0
    if cur == "be":
        value = _be_value(words)
    elif cur == "to" and prev in TO_INFINITIVE:
        value = 0.25
    elif cur == "to" and prev in TO_IDIOM:
        value = -0.35
    elif cur in ("that", "it") and prev in THINK:
        value = 0.35
    return carry, float(value)

