"""Spot a few short English patterns before predicting a negative activation."""
READS = ()

STRONG_MODALS = {'can', 'could', 'cannot'}


def clean(token):
    return token.strip().lower().strip('.,!?;:"()[]{}')


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    position = len(tokens) - 1
    if position < 1:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0

    current = clean(tokens[-1])
    previous = clean(tokens[-2])
    if current == 'be':
        if previous in STRONG_MODALS:
            return None, -1.05
        if previous in {'there', 'then'}:
            return None, -0.7
        if previous == 'also' and position >= 2:
            if prefix.document_ids[-2] == prefix.document_ids[-3]:
                if clean(tokens[-3]) in STRONG_MODALS:
                    return None, -1.05
    return None, 0.0

