"""A mostly lexical negative signal for 'in', weaker for 'for'.

Word boundaries and capitalization matter. Conventional complements such as
'interested in' and 'looking for' weaken the negative response; origin phrases
such as 'coming from' instead have a positive response. The end-of-text marker
is strongly negative. This approximates, rather than parses, these constructions.
Some translations of 'in', the membership sign, and compounds such as 'herein'
get weaker negative values; all remaining tokens get zero. Context is an
80-character tail that resets at document boundaries.
"""
import re

READS = ()


def verb_forms(words):
    """Common regular verb forms, used to recognize a few constructions."""
    forms = set(words.split())
    for word in tuple(forms):
        forms.update((word + 's', word + 'ed', word + 'ing'))
        if word.endswith('e'):
            forms.update((word + 'd', word[:-1] + 'ing'))
        if word.endswith('y'):
            forms.update((word[:-1] + 'ies', word[:-1] + 'ied'))
    return forms


IN_COMPLEMENTS = verb_forms(
    'interest involve result fill engage participate invest specialize'
) | {'included', 'involvement', 'participation', 'investment'}
FOR_COMPLEMENTS = verb_forms('look search ask account need apply') | {
    'quest', 'responsible', 'responsibility', 'ready', 'suitable', 'waiting'
}
FROM_ORIGINS = verb_forms(
    'come arise result derive obtain extract remove isolate differ'
) | {'came', 'arose', 'stem', 'stemmed', 'stemming', 'away', 'apart', 'different'}
CLAUSE_WORDS = set('and but or if that when where whereas whether how '
                   'is are was were be been'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, position = '', 0
    else:
        _, tail, position = carry
    token = prefix.token_strings[-1]
    match = re.search(r'([A-Za-z]+)\s*$', tail)
    word = match.group(1).lower() if match else ''
    bare = token.lstrip(' \t\n\r_./-([{,;:\"\'—')
    separated = bare != token or not tail or not tail[-1].isalpha()
    kind = bare.lower()
    value = 0.0
    if token == '<|endoftext|>':
        value = -1.33
    elif kind == 'in':
        if bare[0].isupper() and bare != 'IN':
            value = -1.57
        elif not separated:
            value = -0.20
        elif word in IN_COMPLEMENTS:
            value = -0.28
        elif word in CLAUSE_WORDS:
            value = -1.52
        elif tail and not tail[-1].isalnum():
            value = -1.46
        else:
            value = -1.24
        if position == 0:
            value -= 0.45
    elif kind == 'for':
        value = -0.38 if token == ' for' else -0.57
        if word in FOR_COMPLEMENTS and separated:
            value = 0.06
        elif not word and token == ' for':
            value = -0.57
    elif kind == 'from':
        value = 0.0 if token == ' from' else -0.47
        if token == ' from':
            if word in FROM_ORIGINS:
                value = 0.27
            elif not word:
                value = -0.29
    elif token.strip() in {'en', 'En', 'EN', 'dans', 'em', 'في'} and separated:
        value = -0.19 if kind == 'em' else -0.33
    elif token.strip() == '∈':
        value = -0.69
    elif kind in {'wherein', 'herein', 'therein'}:
        value = -0.46
    return (doc, (tail + token)[-80:], position + 1), float(value)

