programs.sol:
"""An English -ing action-form detector with a small grammatical context rule.

'By doing' is strongest; progressive auxiliaries, 'for/when doing', and
noun introducers weaken it. Exclude words whose -ing is not an action suffix,
and reduce lexicalized descriptions. Rejoin word pieces; context has less
influence when separated from the ending by several pieces. Else predict
near zero. This is a morphological approximation, not a full syntax parser.
"""
import re

READS = ()
NOT_ACTION_SUFFIX = {
    'thing', 'something', 'anything', 'nothing', 'everything',
    'king', 'ring', 'spring', 'string', 'wing', 'bring', 'sing',
    'beijing', 'morning', 'evening', 'ceiling', 'darling', 'sterling',
    'during', 'according',
}
DESCRIPTIONS = {
    'interesting', 'amazing', 'exciting', 'boring', 'stunning',
    'missing', 'existing', 'remaining', 'underlying', 'outstanding',
    'corresponding', 'following', 'preceding', 'pending',
}
AUXILIARIES = {'am', 'is', 'are', 'was', 'were', 'be', 'been', 'm', 're', 's'}
DETERMINERS = {
    'a', 'an', 'the', 'this', 'these', 'those',
    'my', 'your', 'his', 'her', 'its', 'our', 'their',
}


def context_adjustment(word):
    if word == 'by':
        return 1.70
    if word in {'after', 'without', 'before', 'than'}:
        return 0.30
    if word in {'while', 'as'}:
        return 0.20
    if word in AUXILIARIES or word in {'for', 'when'}:
        return -0.53
    if word in DETERMINERS:
        return -0.40
    if word in {'in', 'with'}:
        return -0.32
    if word == 'to':
        return -0.19
    if word in {'and', 'or'}:
        return 0.10
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0, False)
    _, word, before, pieces, broken = carry
    token = prefix.token_strings[-1]
    for chunk in re.findall(r'[A-Za-z]+|[^A-Za-z]+', token):
        if chunk[0].isascii() and chunk[0].isalpha():
            word += chunk.lower()
        else:
            if word:
                before, broken = word, False
            if not chunk.isspace():
                broken = True
            word, pieces = '', 0
    if word:
        pieces += 1
    value = -0.0025
    if (len(word) > 4 and word.endswith('ing')
            and word not in NOT_ACTION_SUFFIX
            and not word.endswith('string')):
        value += 0.725
        if pieces > 1:
            value -= 0.10
            if token.lower().endswith(('ating', 'izing', 'ising',
                                       'ifying', 'uting', 'ulating')):
                value += 0.285
        if not broken:
            value += context_adjustment(before) * 0.5 ** (pieces - 1)
        if word in DESCRIPTIONS:
            value -= 0.29
    return (doc, word, before, pieces, broken), float(value)

programs.haiku:
"""Fires on -ing verb forms (gerunds and participles) that begin a verb phrase or a
modifier, most strongly right after "by" ("by paying", "by making"), and fairly strongly
after a comma or a clause word ("..., making", "without changing", "after applying").
Weak after articles and copulas ("the building", "is using"), and silent on -ing nouns and
words like "everything" or "during".

Program: find the word the current token completes; if it ends in "-ing" and is not one of
the usual non-verbs, give a strength set by the word just before it."""

READS = ()

NOT_VERBS = {"something", "everything", "anything", "nothing", "thing", "things", "during",
             "according", "morning", "evening", "spring", "string", "king", "ring"}
CLAUSE_WORDS = {",", "without", "after", "before", "while", "as", "than", "then", "thus",
                "like", "and", "or", "so", "but", "that", "also"}
ARTICLES_AND_BE = {"the", "a", "an", "for", "is", "are", "was", "were", "be", "been", "am",
                   "when", "do", "current"}


def step(carry, prefix, upstream):
    text = prefix.text_prefixes[-1]
    # the word that this token ends (letters only, so "substit" + "uting" counts as one)
    start = len(text)
    while start > 0 and text[start - 1].isalpha():
        start -= 1
    word = text[start:].lower()
    if len(word) < 5 or not word.endswith("ing") or word in NOT_VERBS:
        return None, 0.0
    # the word or punctuation mark just before it
    before = text[:start].rstrip()
    if before[-1:].isalpha():
        k = len(before)
        while k > 0 and before[k - 1].isalpha():
            k -= 1
        before_word = before[k:].lower()
    else:
        before_word = before[-1:]
    if before_word == "by":
        return None, 2.3
    if before_word in CLAUSE_WORDS:
        return None, 1.0
    if before_word in ARTICLES_AND_BE:
        return None, 0.2
    return None, 0.6

