ENGLISH_CLASSES = (
    ({'http', 'https'}, -0.53),           # HTTP protocol names
    ({'had', 'could'}, -0.63),           # past auxiliaries
    ({'every'}, -0.77),                  # universal distributive
    ({'each'}, -0.19),                   # individual distributive
    ({'between', 'within'}, -0.66),      # bounded relations
    ({'among', 'amongst', 'inside', 'around', 'behind', 'against'}, -0.31),
    ({'however'}, -0.69),                # contrast
    ({'while'}, -0.26),                  # simultaneity
    ({'require', 'requires', 'required', 'requiring'}, -0.45),
    ({'company', 'companies', 'corporate'}, -0.55),
    ({'big', 'great', 'grand', 'major'}, -0.31),  # size/importance
    ({'before', 'during', 'without', 'through', 'above'}, -0.17),
)

# Each set is an ordinary grammatical or semantic class, not token IDs.
HAN_CLASSES = (
    (set('的了在着和与或都很'), 0.02),  # grammatical function words
    (set('人我你他她它您') | {'我们', '你们', '他们', '自己'}, -0.84),  # persons
    (set('上下内中里'), -0.93),             # spatial positions
    (set('大高好美新真'), -1.10),           # positive qualities
    (set('有不会能可要想将將會') | {'可以'}, -0.68),  # modality, existence, negation
    (set('做打走跑来去进到放') | {
        '工作', '提供', '发展', '建立', '进行', '成为', '实现', '建设', '使用',
    }, -0.63),                            # actions and processes
    (set('也就才还'), -0.54),              # additive/aspectual adverbs
    (set('年月日'), -0.56),                # calendar units
    ({'公司', '企业'}, -1.12),             # business entities
    (set('性化'), -0.81),                  # abstract/transformative suffixes
)
JAPANESE_CASE = {'に', 'で', 'と', 'から', 'まで', 'へ'}
JAPANESE_PARTICLES = {'の', 'は', 'を', 'が'}
KOREAN_PARTICLES = {'의', '이', '가', '은', '는', '을', '를', '와', '과'}
KOREAN_LOCATION = {'에', '에서', '로', '으로', '에게', '부터', '까지'}


def response(s, first):
    if s in DELIMITERS:
        return -0.95 if first and s == '<|im_start|>' else DELIMITERS[s]
    if s.startswith('<|'):
        return -0.03
    if s == '\r':
        return -0.75
    if not s.strip():
        return 0.003
    if first and s == '#':
        return 0.31

    # Standalone markup symbols differ from space-prefixed ones.
    symbol = s.lstrip(' ')
    spaced = s.startswith(' ')
    if symbol in SYMBOLS:
        return SYMBOLS[symbol][int(spaced)]
    if s == '\\' or s.startswith('\\x'):
        return -0.55
    if s in {'\\"', ' \\"'}:
        return -0.24 if spaced else -0.47
    if s == '“':
        return -0.48
    if s == '”':
        return -0.22
    if s in {'?', ' ?'}:
        return -0.13

    w = s.strip()
    word = w.lower()
    for words, value in ENGLISH_CLASSES:
        if word in words:
            return value

    for words, value in HAN_CLASSES:
        if w in words:
            return value
    if w == '第':                         # Chinese ordinal prefix
        return -0.94
    if w in JAPANESE_CASE:
        return -0.70
    if w in JAPANESE_PARTICLES:
        return 0.003
    if w in KOREAN_PARTICLES:
        return 0.05
    if w in KOREAN_LOCATION:
        return -0.59
    if '\ufffd' in w:
        return -0.05

    names = [unicodedata.name(c, '') for c in w if c.isalpha()]
    if any('CJK' in n for n in names):
        return -0.10
    if any('HIRAGANA' in n or 'KATAKANA' in n for n in names):
        return -0.17
    if any('HANGUL' in n for n in names):
        return -0.17
    if any('THAI' in n for n in names):
        return -0.20
    if any('ARABIC' in n for n in names):
        return -0.08
    if any('CYRILLIC' in n for n in names):
        return -0.04
    if w.isdigit():
        return 0.001
    return -0.01 if names else -0.002


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    first = carry is None or carry != doc
    return doc, response(prefix.token_strings[-1], first)

programs.luna:
"""A compact heuristic for this down-projection component: it predicts its strong
negative responses to chat-control markers and East Asian writing, treats digit
tokens as nearly neutral, and otherwise uses the small average activation. It
misses most word-specific and contextual variation.
"""
import unicodedata

READS = ()

CHAT_MARKERS = {
    "<|im_start|>": -0.8,
    "<|im_end|>": -1.6,
    "<tool_call>": -2.0,
    "</tool_call>": -0.95,
    "<tool_response>": -2.65,
    "</tool_response>": -2.05,
    "<think>": -0.95,
    "</think>": -0.75,
}


def east_asian(character):
    name = unicodedata.name(character, "")
    return any(script in name for script in (
        "CJK UNIFIED IDEOGRAPH", "CJK COMPATIBILITY IDEOGRAPH",
        "HIRAGANA", "KATAKANA", "HANGUL",
    ))


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in CHAT_MARKERS:
        return None, float(CHAT_MARKERS[token])
    if any(east_asian(character) for character in token):
        return None, -0.14
    if any(character.isdigit() for character in token):
        return None, 0.0
    return None, -0.02

programs.sol:
"""Approximate an input/output vocabulary detector, especially printing.

Printing/logging words get strong positive responses; input and node names get
moderate responses. CamelCase program names and standard C library calls get
smaller responses, while declaration/control keywords are weakly negative.
A few UI-setup and serialization operations are also recognized.
Long CamelCase names get a stronger API-name response than short ones.
The preceding token distinguishes console.log, indentation, and with exit.
"""
import re

READS = ()

C_LIBRARY = set('malloc calloc realloc strcpy strcmp strlen strcat memcpy memset '
                'atoi atof scanf sscanf getchar fgets fopen fclose feof stdlib '
                'unistd fwrite getline'.split())
KEYWORDS = set('int bool boolean private protected while import new def error '
               'package using'.split())


def response(token, previous):
    word = re.sub(r'^[\W_]+|[\W_]+$', '', token)
    low = word.lower()
    method = token.startswith('.')
    space = token.startswith(' ')
    if low == 'printstacktrace':
        return 1.84
    if low == 'println':
        return 1.97 if word == 'Println' and method else (1.55 if method else 1.38)
    if low in {'writeline', 'writeln'}:
        return 1.64
    if low in {'printf', 'fprintf', 'perror'}:
        return 1.41 if word == 'Printf' and method else 0.83
    if low in {'sprintf', 'snprintf'}:
        return 0.84
    if low in {'print', 'prints', 'printing'}:
        if token[:1].isspace() and previous.isspace():
            return 1.16
        return 1.00 if low == 'print' else 0.88
    if low in {'printed', 'reprint', 'imprint', 'footprint', 'fingerprint'}:
        return 0.64
    if low in {'printer', 'printers', 'printable', 'blueprint'}:
        return 0.48
    if word in {'印', '打印', '印刷'}:
        return 1.20 if word == '印' else 0.80
    if token == '.log':
        if previous.strip() == 'console':
            return 1.27 if previous.startswith(' ') else 1.40
        return 0.49
    if low == 'console' or word == 'System':
        return 0.46 if word == 'Console' else 0.27
    if token == '.out':
        return 0.75
    if word in {'cout', 'stdio', 'iostream'}:
        return 0.82
    if word == 'endl':
        return 0.63
    if word in {'stdin', 'stdout', 'stderr', 'cin', 'cerr', 'ostream', 'ifstream'}:
        return 0.35
    if low == 'echo':
        return 0.43
    if low in {'log', 'logger', 'debug'}:
        return 0.19
    if low == 'node':
        if token.startswith('/'):
            return 0.58
        if token.startswith('('):
            return 0.49
        return 0.67 if space and word == 'node' else 0.77
    if low == 'nodes':
        return 0.52
    if word.endswith('Node'):
        return 0.83
    if low == 'input':
        return 0.75 if word[0].isupper() else (0.56 if space else 0.66)
    if low == 'inputs' or word == '输入':
        return 0.56
    if low == 'exit':
        return 0.59 if previous.strip() == 'with' else 0.37
    if low in {'cell', 'cells', 'edge', 'vertex', 'vertices'}:
        return 0.17
    if low in {'app', 'document', 'window', 'open'}:
        return 0.19
    if word in C_LIBRARY:
        return 0.68
    if word in {'viewDidLoad', 'setContentView'}:
        return 1.75
    if word in {'stringify', 'dumps', 'jsonify', 'toFixed', 'hexdigest'}:
        return 1.20 if not space else 0.35
    if low in KEYWORDS:
        return -0.07
    if re.fullmatch('[A-Za-z]+', word) and re.search('[a-z][A-Z]', word):
        if len(word) > 12:
            return 0.70 if method else 0.50
        return 0.30 if method else 0.16
    return 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), float(response(token, previous))

programs.luna:
"""A lightweight detector for code that sends text to an output stream.

This component is often positive on print statements, console logging, and
output-stream names, so the current token supplies a rough output cue.
"""
READS = ()

PRINT_WORDS = {
    "print", "prints", "printf", "fprintf", "sprintf", "cout",
    "perror", "echo", "打印",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    word = token.strip("._")
    if word in {"println"}:
        return None, 1.45
    if word in PRINT_WORDS:
        return None, 0.95
    if token in {".log", ".info"}:
        return None, 1.15
    if word in {"out", "stdout", "stderr"}:
        return None, 0.65
    if word == "exit":
        return None, 0.55
    return None, 0.0

programs.sol:
"""A surface-spelling approximation to a separately encoded vowel detector.

Predict a negative pulse for individual vowels, with larger letter-specific
responses in Greek and accented Latin. A consonant-only preceding fragment
makes the pulse strongest; vowels in that fragment and word boundaries soften
it. Written vowel marks have fixed negative responses. Byte-split marks are
recognized from the decoded text; NUL-separated spelling is handled explicitly.
Other tokens normally predict zero. These are fitted spelling rules, not an
exact account of all contextual variation in the component.
"""
import unicodedata as ud
from functools import lru_cache

READS = ()

# Peak responses to vowel letters, grouped by writing system.
LATIN = dict(zip('aeiouy', (-0.65, -0.52, -0.40, -0.54, -0.30, -0.13)))
ACCENTED = {
    'á': -1.0, 'à': -0.9, 'â': -1.1, 'ä': -1.35, 'å': -1.1,
    'ā': -2.3, 'ă': -1.1, 'ą': -0.4, 'é': -0.72, 'è': -1.1,
    'ê': -0.85, 'ě': -0.95, 'ę': -0.55, 'í': -0.9, 'ï': -0.65,
    'ó': -0.95, 'ö': -1.25, 'ō': -1.2, 'ü': -0.65, 'ū': -1.1,
    'ů': -0.8, 'ő': -0.6, 'ű': -0.9,
    'æ': -1.0, 'ø': -0.9, 'œ': -0.4, 'ə': -1.6,
    'ɛ': -1.1, 'ɔ': -1.5, 'ı': -0.55,
}
GREEK = dict(zip('αεηιουω', (-2.2, -0.88, -1.2, -0.52, -1.55, -0.74, -0.54)))
CYRILLIC = dict(zip('аеиоуыэюяёієї',
                    (-0.68, -0.74, -0.55, -0.56, -0.53, -0.50,
                     -1.35, -0.18, -0.18, -1.45, -0.90, -0.58, 0.0)))
ARMENIAN = dict(zip('աեէըիոօ', (-3.7, -1.2, -1.1, -0.9, -0.9, -2.5, -2.5)))
HEBREW_POINTS = dict(zip('ְֱֲֳִֵֶַָֹֻּ',
                        (-1.4, -0.75, -1.1, -1.0, -1.6, -2.1,
                         -1.9, -2.0, -3.0, -1.35, -1.0, -1.0)))
ARABIC = {'ا': -0.52, 'و': -0.30, 'ي': -0.20, 'ی': -0.42, 'ى': -0.3}
VOWEL_SIGNS = {'َ': -2.2, 'ُ': -0.9, 'ِ': -0.75,
               'ั': -1.3, 'ิ': -0.6, 'ี': -0.25, 'ึ': -0.45,
               'ื': -0.7, 'ุ': -0.75, 'ู': -0.65, '็': -0.95}

# Nasal N and S-like sibilant endings weaken the pulse; labials strengthen it.
N_ENDINGS = set('nνнن')
SIBILANTS = set('sxσςξсس')
LABIALS = set('mbpfvwμπβφмбпфвمبفپ')
OTHER_VOWELS = ACCENTED | CYRILLIC | ARMENIAN | ARABIC


def base_letter(c):
    return ud.normalize('NFD', c.lower())[0]


def is_vowel(c):
    base = base_letter(c)
    return (base in LATIN or base in GREEK or c.lower() in CYRILLIC
            or c.lower() in ACCENTED or c in ARABIC
            or c.lower() in ARMENIAN)


@lru_cache(maxsize=32768)
def response(s, prev):
    if s == '\x00':
        return -0.5
    for ch in s:
        name = ud.name(ch, '')
        if 'VOWEL SIGN' in name:
            sound = name.rsplit(' ', 1)[-1]
            return {'AA': -1.35, 'A': -0.8, 'I': -0.35, 'E': -0.65,
                    'U': -0.55, 'UU': -0.4}.get(sound, -0.6)
    core = s.lstrip(' \t._-/')
    if len(core) != 1:
        if core == 'ου':
            return -0.55
        return 0.0
    c = core.lower()
    name = ud.name(core, '')
    if name.startswith(('MATHEMATICAL', 'FULLWIDTH', 'MODIFIER LETTER')):
        plain = ud.normalize('NFKD', c)
        if plain in LATIN:
            return min(-0.65, 1.8 * LATIN[plain])
    if c in HEBREW_POINTS:
        return HEBREW_POINTS[c]
    base = base_letter(c)
    if c in VOWEL_SIGNS:
        return VOWEL_SIGNS[c]
    marked = len(ud.normalize('NFD', c)) > 1
    if base in LATIN:
        peak = ACCENTED.get(c, -0.85) if marked else LATIN[base]
    elif base in GREEK:
        peak = GREEK[base] * (0.75 if marked else 1.0)
    elif c in OTHER_VOWELS:
        peak = OTHER_VOWELS[c]
    else:
        return 0.0
    if core.isupper() and c in 'аеиоу':
        peak = -1.85

    letters = [ch for ch in prev if ch.isalpha()]
    n_vowels = sum(is_vowel(ch) for ch in letters)
    last = prev[-1:]
    follows_consonant = bool(last) and last.isalpha() and not is_vowel(last)
    if prev == '\x00' and base in LATIN:
        return -1.25 if base == 'e' else -0.95
    if s[0].isspace():
        if base == 'α':
            return -0.9 if letters and not n_vowels else -0.48
        return peak * 0.65 if letters and not n_vowels else 0.02
    if not follows_consonant:
        if base in 'αο':
            return -0.6 if base == 'α' else -0.4
        if last.isdigit() and base in LATIN:
            return -0.09
        return 0.04 if last.isspace() or (last and is_vowel(last)) else -0.02

    # Vowels within the preceding fragment soften a consonant-to-vowel pulse.
    factor = (0.4 if marked else 0.22) ** n_vowels
    ending = base_letter(last)
    if ending in N_ENDINGS or ending in SIBILANTS:
        factor *= 0.8
    elif ending in LABIALS:
        factor *= 1.12
    return float(peak * factor)


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    # Byte fragments can complete a vocalization mark even though they decode
    # alone as a replacement character. Read text only for these rare tokens.
    if '\ufffd' in s and carry is not None and carry[0] == doc:
        completed = prefix.text_prefixes[-1][-1:]
        if completed and (completed in HEBREW_POINTS or
                          'VOWEL SIGN' in ud.name(completed, '')):
            return (doc, s), response(completed, prev)
    return (doc, s), response(s, prev)

programs.luna:
"""Estimate a negative response to words about scope, access, and position.

Internal/external language gets the strongest response; public/private,
inside/outside, and related status or relation words get a smaller one.
"""

READS = ()

RELATION_WORDS = {
    "public", "publicly", "private", "privately",
    "official", "officially", "inside", "outside",
    "implicit", "implicitly", "absolute", "absolutely",
    "relative", "relatively", "own", "自身",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word.startswith(("internal", "external")):
        return None, -7.2
    if word in {"intern", "extern"}:
        return None, -3.5
    if word in RELATION_WORDS:
        return None, -0.9
    if word == "ext":
        return None, -0.5
    return None, 0.0

programs.sol:
"""A lexical asterisk/star/heart/interest detector, with comment syntax.

Single asterisks are strong; double stars and comment delimiters are weak.
An indented comment-line star is weaker, and the first after /** is negative.
Star, heart, and interest vocabulary has positive values, as do a few common
interest phrases. Unrecognized tokens get zero. Keep only recent line text
and the previous word; reset this state at each new document.
"""
import math
import re

READS = ()
INTEREST_WORDS = {'interest', 'interests', 'interested', 'interesting'}


def word_signal(token):
    word = token.strip().lstrip('._-').lower()
    if word in INTEREST_WORDS:
        value = 1.9 if word == 'interest' else 1.4
        return value if token.startswith(' ') else value * 0.78
    if word.startswith(('interess', 'interes', 'intéress', 'интерес')):
        return 1.0
    if word == 'fascinating':
        return 1.0
    if word in {'interestingly', 'fascinated', 'fascination', 'passion',
                'passionate', 'boring', 'intriguing'}:
        return 0.5
    if word == 'star':
        return 1.25
    if word in {'stars', 'starred', 'starring'}:
        return 0.8
    if 'heart' in word:
        return 0.67
    if '感兴趣' in word or '感興趣' in word:
        return 2.4
    if word in {'兴趣', '興趣'}:
        return 1.35
    if word in {'有趣', '有趣的', '利息', '利率', '关心', '관심', '星'}:
        return 1.0
    if word in {'心', '的心', '息'}:
        return 0.85
    if word in {'趣', '趣味', '明星', '女星'} or '☆' in word:
        return 0.7
    if '＊' in word:
        return 1.25
    return 0.0


def star_signal(token, line, previous_line):
    text = token.strip()
    spaced, newline = token.startswith(' '), '\n' in token
    count = text.count('*')
    if text.startswith('/**'):
        return 0.0
    if text.startswith('/*'):
        return -0.25 if newline else 0.2
    if '*/' in text:
        if spaced:
            return 0.0 if newline else 0.46
        return 0.3 if newline else 0.96
    if count == 2:
        return -0.15 if spaced else 0.03
    if count >= 3:
        return min(1.3, 0.45 + 0.18 * math.log(count))
    if text != '*':
        if any(c.isalpha() for c in text):
            return 1.4 if any(c.isupper() for c in text) else 1.2
        return 1.7 if text.endswith('*') or text == '*(' else 1.25
    if newline:
        return 0.8 if spaced else 1.35
    margin = line.lstrip('+-')
    numbered = bool(re.fullmatch(r'\s*\d+\t\s*', margin))
    if not margin.strip() or numbered:
        if token == '*':
            return 2.06
        if previous_line.rstrip().endswith('/**'):
            if numbered:
                return 0.15
            return -0.75 if margin else 0.0
        return 0.85 if margin else 1.2
    if re.search(r'\b(?:char|int|float|double)\s*$', line):
        return 0.9
    if line.rstrip()[-1:].isdigit():
        return 1.48 if spaced else 1.64
    return 1.7 if spaced else 1.9


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, previous_line, last_word = '', '', ''
    else:
        _, line, previous_line, last_word = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = (star_signal(token, line, previous_line)
             if '*' in token else word_signal(token))
    if value == 0.0 and last_word in INTEREST_WORDS:
        if word == 'of':
            value = 0.5
        elif word in {'in', 'to', 'on', 'for', 'rate', 'rates'}:
            value = 0.3
    elif value == 0.0 and 'heart' in last_word and word == 'of':
        value = 0.3
    lines = (line + token).split('\n')
    if len(lines) > 1:
        previous_line = lines[-2][-200:]
    return (doc, lines[-1][-200:], previous_line, word), float(value)

programs.luna:
"""A small lexical proxy for a layer-0 relation/focus detector.

The component is usually quiet, but rises on words that link, pair, or
contrast things (especially “both” and “between”).
"""
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    word = word.strip(".,;:!?()[]{}\"'“”‘’")

    # Paired or relational language: the score is larger for the clearest
    # English triggers and smaller for weaker relatives.
    if word == "both":
        return None, 4.0
    if word in {"between", "respectively"}:
        return None, 0.85 if word == "between" else 1.15
    if word in {"whether", "only", "nor", "former", "respective"}:
        return None, {
            "whether": 1.1,
            "only": 1.0,
            "nor": 0.7,
            "former": 0.85,
            "respective": 0.75,
        }[word]
    if word in {
        "either", "neither", "latter", "combination", "entre", "option"
    }:
        return None, 0.8
    if word in {"ただ", "除了"}:
        return None, 0.8

    return None, 0.0

programs.sol:
"""Surface cues for assignment, equality, and formal stipulation.

The largest negative responses are to := and leftward assignment arrows.
Ordinary = is weaker after numbers and mathematical expressions than after
names; nearby code/math notation adjusts this estimate. 'shall', 'set forth',
and a few formal English words and literary Chinese particles are side cues.
These rules approximate the strong training responses, deliberately ignoring
many weaker word-specific effects. State resets at each document boundary.
"""
import re

READS = ()
FORMAL_WORDS = {
    ' herein': -0.84,
    ' therein': -0.69,
    ' thereof': -0.57,
    ' duly': -0.85,
    ' ought': -0.91,
    ' unto': -0.63,
}
LITERARY_PARTICLES = {
    '乃': -6.16,
    '乃是': -2.34,
    '遂': -2.52,
    '皆': -2.18,
    '于是': -1.14,
    '於是': -0.88,
}
RELATION_MARKS = {
    '←': -3.79,
    '≈': -0.43,
    '≡': -0.71,
    '==': 0.17,
    '===': 0.17,
    '<=': -0.36,
    '>=': -0.22,
    '!=': -0.11,
