PRECISION = frozenset('''
    exactly precisely certainly definitely surely clearly obviously
'''.split())
TOTALITY = frozenset('whole entire wholly entirely entirety'.split())
IDENTITY = frozenset('same other another different'.split())
INDEFINITE = frozenset('any some'.split())
INITIALITY = frozenset('first initial primary previous prior'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    text = token.strip()
    lower = text.lower()
    last = previous[-1:].lower() or '?'
    penult = previous[-2:-1].lower() or '?'
    vowel_liquid = last in 'rl' and penult in 'ao'
    reset = not previous or previous == '<|endoftext|>'
    value = -0.001

    # A short fragment beginning with y is more sensitive than a whole word.
    if lower == 'y':
        if reset:
            value = -0.57 if text == 'Y' else -0.70
            if token[:1].isspace():
                value += 0.17 if text == 'Y' else 0.11
        elif last in 'rl':
            value = 0.43 if text == 'Y' else 0.15
        elif last == 'y':
            value = -0.35
        elif last == 'w':
            value = -0.08
        elif text == 'Y' and last.isalpha():
            value = 0.10
        else:
            value = -0.03
    elif (token[:1].lower() == 'y' and token.isalpha()
          and len(token) <= 4
          and lower not in {'you', 'your', 'yes', 'year'}):
        if last == 'r':
            value = 0.31
        elif last == 'l':
            value = 0.27
        elif last == 'y':
            value = -0.53
        elif last == 'w':
            value = -0.15
        elif last == 'o':
            value = 0.30
        elif last in 'szdb':
            value = 0.16
        else:
            value = 0.04
        if vowel_liquid:
            value += 0.15
        elif last in 'sd' and penult == 'a':
            value += 0.18
        elif last == 'o' and penult == 'r':
            value += 0.10
        elif last == 'g' and penult == 'n':
            value -= 0.25
    elif token in {'iness', 'ily', 'ies', 'ied', 'ier', 'iest', 'ly'}:
        base = {'iness': 0.19, 'ily': 0.22, 'ies': 0.035, 'ied': 0.01,
                'ier': 0.0, 'iest': 0.02, 'ly': 0.04}[token]
        gain = 0.10 if token in {'ly', 'ier', 'iest'} else 0.22
        value = base + (gain if last in 'rl' else 0.0)
        if vowel_liquid and token in {'iness', 'ily', 'ies', 'ied'}:
            value += 0.20
        if last in 'wy':
            value -= 0.16
    elif lower == 'js':
        value = -0.28
    elif previous.lower().endswith('y') and token.isalpha():
        # Short continuations after y, excluding ordinary inflection endings.
        initial = lower[:1]
        if token not in {'s', 'es', 'ed', 'ing', 'er', 'ly'}:
            if initial in 'jxy':
                value = -0.36 if len(token) <= 2 else -0.13
            elif initial in 'dkq':
                value = -0.29 if len(token) <= 2 else -0.12
            elif initial in 'iegvw':
                value = -0.14 if len(token) <= 2 else -0.07
            elif initial == 't':
                value = -0.09 if len(token) <= 2 else -0.035
    elif (lower in {'ks', 'ds'} and token[:1].isalpha()
          and last in 'rl'):
        value = 0.27
    elif (vowel_liquid and token.isalpha() and len(token) <= 4):
        # Short spelling continuations after ar/or/al/ol.
        initial = lower[:1]
        if initial in 'dkqjx':
            value = 0.17 if len(token) <= 2 else 0.08
        elif initial in 'cgvmw':
            value = 0.08 if len(token) <= 2 else 0.045
        elif initial in 'ie':
            value = 0.04
        elif initial == 't':
            value = 0.04
        elif initial == 'a':
            value = 0.03
    elif lower == 'j':
        value = -0.025
    elif text.isdigit():
        value = 0.003

    # Smaller lexical offsets for English modifiers and conversation markup.
    if token[:1].isspace() or reset:
        if lower in TOTALITY:
            value = -0.11
        elif lower in PRECISION:
            value = -0.07
        elif lower in INITIALITY:
            value = -0.05
        elif lower in IDENTITY:
            value = -0.04
        elif lower in INTENSIFIERS:
            value = -0.04
        elif lower in HEDGES:
            value = -0.04
        elif lower in INDEFINITE:
            value = 0.045
    if token == '<|im_start|>':
        value = 0.031
    elif token == '<think>':
        value = 0.07
    return (doc, token), float(value)

